INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-2327', 'Dumbbell Reverse Grip Row (Female)', 'back', 'upper back', '["biceps","forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ आपके शरीर की ओर हों।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कमर के बल आगे की ओर झुकें।","अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को सीधा नीचे लटकने दें, पूरी तरह फैला हुआ रखें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, डम्बल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0384', 'Dumbbell Reverse Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Hold a dumbbell in each hand with an underhand grip, palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी ऊपरी बांहों को पैड पर और अपनी छाती को सहारे पर टिकाकर एक उपदेशक बेंच पर बैठें।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ ऊपर की ओर।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को मोड़ें।","डम्बल को तब तक मोड़ना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1675', 'Dumbbell Reverse Spider Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों और भुजाएँ पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0385', 'Dumbbell Reverse Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ नीचे की ओर हों।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, डम्बल को अपने शरीर की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1459', 'Dumbbell Romanian Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी पीठ को सीधा और अपने कोर को व्यस्त रखते हुए, कूल्हों पर टिकाएं और डम्बल को जमीन की ओर झुकाएं, जिससे आपके घुटने थोड़े मुड़ जाएं।","जब तक आप अपनी हैमस्ट्रिंग में खिंचाव महसूस न करें तब तक डम्बल को नीचे रखें, फिर अपनी एड़ियों से धक्का दें और अपने ग्लूट्स को जोड़कर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0386', 'Dumbbell Rotation Reverse Fly', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Rotate your arms so that your palms are facing downwards.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों में डंबल पकड़ लें, हथेलियां अंदर की ओर हों।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें।","अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे फर्श के समानांतर न हो जाएं।","अपनी भुजाओं को इस प्रकार घुमाएँ कि आपकी हथेलियाँ नीचे की ओर हों।","धीरे-धीरे अपनी भुजाओं को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2397', 'Dumbbell Scott Press', 'shoulders', 'delts', '["triceps","chest"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ आगे की ओर हों।","अपनी कोहनियों को मोड़कर और हथेलियों को आगे की ओर रखते हुए डम्बल को कंधे की ऊंचाई तक उठाएं।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0387', 'Dumbbell Seated Alternate Front Raise', 'shoulders', 'delts', '["trapezius","biceps"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","प्रत्येक हाथ में एक डम्बल पकड़ें, अपनी हथेलियों को अपने शरीर की ओर रखें और भुजाएँ अपनी तरफ नीचे की ओर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए, एक डम्बल को अपने सामने तब तक उठाएँ जब तक कि वह ज़मीन के समानांतर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं के बीच वैकल्पिक करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1676', 'Dumbbell Seated Alternate Hammer Curl On Exercise Ball', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेलियों को अपने शरीर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपनी हथेली को अपने शरीर की ओर रखते हुए एक डम्बल को अपने कंधे की ओर मोड़ें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","विपरीत भुजा से भी यही क्रिया दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0388', 'Dumbbell Seated Alternate Press', 'shoulders', 'delts', '["triceps","chest"]', 'dumbbell', 'strength', 'beginner', '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press one dumbbell up overhead, fully extending your arm.","Lower the dumbbell back down to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ आगे की ओर हों।","अपनी कोहनियों को मोड़कर और हथेलियों को आगे की ओर रखते हुए डम्बल को कंधे की ऊंचाई तक उठाएं।","अपनी बांह को पूरी तरह फैलाते हुए एक डम्बल को ऊपर की ओर दबाएं।","डम्बल को वापस कंधे की ऊँचाई तक नीचे लाएँ।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', '["Seated_Dumbbell_Press/0.jpg","Seated_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3546', 'Dumbbell Seated Alternate Shoulder', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Continue alternating between arms for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ अंदर की ओर हों, और उन्हें कंधे की ऊँचाई तक उठाएँ।","एक डम्बल को ऊपर की ओर दबाएं जबकि दूसरे डम्बल को कंधे की ऊंचाई पर रखें।","उठे हुए डम्बल को वापस कंधे की ऊँचाई तक नीचे लाएँ और साथ ही दूसरे डम्बल को ऊपर की ओर दबाएँ।","दोहराव की वांछित संख्या के लिए भुजाओं के बीच बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0389', 'Dumbbell Seated Bench Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up above your head.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को सीधे अपने सिर के ऊपर फैलाएँ।","अपनी कोहनियों को अपने कानों के पास रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2317', 'Dumbbell Seated Bent Arm Lateral Raise', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक डम्बल पकड़ें और आपकी भुजाएँ 90 डिग्री के कोण पर मुड़ी हुई हों।","अपनी कोहनियों को मोड़ते हुए, अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक वे ज़मीन के समानांतर न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1730', 'Dumbbell Seated Bent Over Alternate Kickback', 'upper arms', 'triceps', '["shoulders","back"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, palms facing inwards.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ अंदर की ओर हों।","अपनी पीठ को सीधा और जमीन के समानांतर रखते हुए कमर के बल आगे की ओर झुकें।","एक हाथ को पीछे की ओर सीधा फैलाएं, इसे अपने शरीर के करीब रखें, जब तक कि आपका हाथ पूरी तरह से फैल न जाए।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1737', 'Dumbbell Seated Bent Over Triceps Extension', 'upper arms', 'triceps', '["shoulders","back"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your head up.","Extend your arms straight back, keeping your elbows close to your head.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी पीठ सीधी और सिर ऊपर रखते हुए कमर के बल आगे की ओर झुकें।","अपनी कोहनियों को अपने सिर के पास रखते हुए, अपनी भुजाओं को पीछे की ओर सीधा फैलाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1677', 'Dumbbell Seated Bicep Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपनी पीठ सीधी रखें और अपनी कोहनियाँ अपने धड़ के पास रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0390', 'Dumbbell Seated Biceps Curl (On Stability Ball)', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक स्टेबिलिटी बॉल पर बैठें।","अपनी हथेलियों को आगे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3547', 'Dumbbell Seated Biceps Curl To Shoulder Press', 'upper arms', 'biceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","अपनी हथेलियों को आगे की ओर रखते हुए और बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी कोहनियों को अपनी भुजाओं के पास रखते हुए, डम्बल को अपने कंधों की ओर मोड़ें।","एक बार जब आपके अग्रबाहु लंबवत हो जाएं, तो अपनी कलाइयों को घुमाएं ताकि आपकी हथेलियां आगे की ओर हों।","डम्बल को सिर के ऊपर तब तक दबाएँ जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएँ।","गति को उलट कर डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1379', 'Dumbbell Seated Calf Raise', 'lower legs', 'calves', '["hamstrings"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Hold onto the dumbbell for stability.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपनी जांघों पर डम्बल रखकर एक बेंच या कुर्सी पर बैठें।","अपने पैरों के पंजों को किसी ऊंची सतह जैसे सीढ़ी या ब्लॉक पर रखें, जिसमें आपकी एड़ियाँ किनारे से लटकी हुई हों।","स्थिरता के लिए डम्बल को पकड़ें।","अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर का वजन अपने पैरों की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0391', 'Dumbbell Seated Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल, हथेलियाँ आगे की ओर हों।","अपनी पीठ सीधी रखें और अपनी कोहनियाँ अपने धड़ के पास रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Seated_Dumbbell_Curl/0.jpg","Seated_Dumbbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0392', 'Dumbbell Seated Front Raise', 'shoulders', 'delts', '["trapezius","biceps"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल, अपनी जाँघों पर टिकाएँ।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपनी हथेलियों को नीचे की ओर रखते हुए डम्बल को अपने सामने उठाएं, जब तक कि वे कंधे के स्तर पर न आ जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1678', 'Dumbbell Seated Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ आपके धड़ की ओर हों और भुजाएँ सीधी नीचे की ओर फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0393', 'Dumbbell Seated Inner Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपनी ऊपरी भुजाओं को अपनी जाँघों पर टिकाएँ, जिससे डम्बल नीचे लटक जाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर डम्बल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Seated_Dumbbell_Inner_Biceps_Curl/0.jpg","Seated_Dumbbell_Inner_Biceps_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0394', 'Dumbbell Seated Kickback', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend your knees slightly and lean forward from your hips, keeping your back straight.","Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए अपने कूल्हों से आगे की ओर झुकें।","अपनी ऊपरी भुजाओं को अपनी भुजाओं के पास लाएँ और अपनी कोहनियों को 90 डिग्री के कोण पर मोड़ें।","अपनी भुजाओं को पीछे की ओर सीधा फैलाएँ, अपनी ट्राइसेप्स को गति के शीर्ष पर दबाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0396', 'Dumbbell Seated Lateral Raise', 'shoulders', 'delts', '["traps","upper back"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल, अपनी जाँघों पर टिकाएँ।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपनी कोहनियों को थोड़ा मोड़कर डम्बल को अपनी तरफ उठाएं, जब तक कि आपकी भुजाएं जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0395', 'Dumbbell Seated Lateral Raise v. 2', 'shoulders', 'delts', '["traps","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल, अपनी जाँघों पर टिकाएँ।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपनी कोहनियों को थोड़ा मोड़कर डम्बल को अपनी तरफ उठाएं, जब तक कि आपकी भुजाएं जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0397', 'Dumbbell Seated Neutral Wrist Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Rest your forearms on your thighs, allowing the dumbbells to hang down.","Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ एक दूसरे के सामने हों।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे डम्बल नीचे लटक जाएँ।","अपनी कलाइयों को तटस्थ स्थिति में रखते हुए, डम्बल को अपने कंधों की ओर ऊपर की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1679', 'Dumbbell Seated One Arm Bicep Curl On Exercise Ball With Leg Raised', 'upper arms', 'biceps', '["forearms","shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Place your other hand on your hip for stability.","Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेली को ऊपर की ओर रखते हुए और अपने हाथ को पूरी तरह फैलाकर एक हाथ में डम्बल पकड़ें।","स्थिरता के लिए अपना दूसरा हाथ अपने कूल्हे पर रखें।","अपनी ऊपरी भुजा को स्थिर रखते हुए धीरे-धीरे डम्बल को अपने कंधे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।","हथियार बदलें और व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0398', 'Dumbbell Seated One Arm Kickback', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें।","अपने धड़ को कमर के बल आगे की ओर झुकाएं, अपनी पीठ को सीधा और जमीन के समानांतर रखें।","अपनी कोहनी को अपने शरीर के पास रखते हुए, अपना हाथ सीधा पीछे की ओर फैलाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0399', 'Dumbbell Seated One Arm Rotate', 'lower arms', 'forearms', '["shoulders","biceps"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपनी पीठ सीधी करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, इसे अपनी जांघ पर रखें।","अपनी कोहनी को अपने शरीर के करीब रखते हुए डंबल को कंधे की ऊंचाई तक उठाएं।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपने अग्रबाहु को अपने शरीर से दूर बाहर की ओर घुमाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने अग्रबाहु को वापस प्रारंभिक स्थिति में घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0400', 'Dumbbell Seated One Leg Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'dumbbell', 'strength', 'beginner', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.","Extend your left leg straight out in front of you, keeping your foot flexed.","Place the ball of your right foot on an elevated surface, such as a step or weight plate.","Using your calf muscles, raise your right heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच या कुर्सी पर बैठें और डम्बल को अपनी दाहिनी जांघ पर रखें।","अपने बाएं पैर को अपने सामने सीधा फैलाएं, अपने पैर को मोड़कर रखें।","अपने दाहिने पैर की गेंद को किसी ऊँची सतह, जैसे स्टेप या वेट प्लेट, पर रखें।","अपनी पिंडली की मांसपेशियों का उपयोग करते हुए, अपनी दाहिनी एड़ी को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', '["Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg","Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1380', 'Dumbbell Seated One Leg Calf Raise - Hammer Grip', 'lower legs', 'calves', '["hamstrings","glutes"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपनी जांघों पर डम्बल रखकर एक बेंच या कुर्सी पर बैठें।","एक पैर को किसी ऊंची सतह पर रखें, जैसे कि सीढ़ी या ब्लॉक, और आपकी एड़ी किनारे से लटकी हुई हो।","डम्बल को हथौड़े की पकड़ से पकड़ें, यानी आपकी हथेलियाँ एक-दूसरे के सामने हों और आपकी उंगलियाँ हैंडल के चारों ओर लिपटी हों।","अपने कोर को व्यस्त रखते हुए और अपनी पीठ को सीधा रखते हुए, धीरे-धीरे अपने पैर की गेंद से धक्का देकर अपनी एड़ी को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ, फिर दूसरे चरण पर जाएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1381', 'Dumbbell Seated One Leg Calf Raise - Palm Up', 'lower legs', 'calves', '["hamstrings","glutes"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your back straight and your feet flat on the ground.","Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["अपनी पीठ सीधी करके और अपने पैरों को ज़मीन पर सपाट करके एक बेंच या कुर्सी पर बैठें।","एक हाथ में डम्बल पकड़ें और इसे अपनी जांघ के ऊपर रखें, हथेली ऊपर की ओर रखें।","एक पैर को जमीन से ऊपर उठाएं और इसे अपने सामने फैलाएं, अपने घुटने को थोड़ा मोड़कर रखें।","अपने पैर की गेंद से धक्का देकर अपनी एड़ी को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0401', 'Dumbbell Seated Palms Up Wrist Curl', 'lower arms', 'forearms', '["biceps","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, अपने अग्रबाहुओं को गति के शीर्ष पर निचोड़ें।","एक पल के लिए रुकें, फिर अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg","Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0402', 'Dumbbell Seated Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher curl bench with your feet flat on the floor.","Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को फर्श पर सपाट करके प्रीचर कर्ल बेंच पर बैठें।","एक हाथ में डंबल को अंडरहैंड ग्रिप से पकड़ें, अपनी ऊपरी भुजा को उपदेशक पैड पर टिकाएं।","अपनी ऊपरी भुजा को स्थिर रखते हुए सांस छोड़ें और डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0403', 'Dumbbell Seated Revers Grip Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, हथेली ऊपर की ओर रखें।","अपनी कोहनी को अपनी जांघ के अंदर, घुटने के ठीक ऊपर रखें।","अपनी ऊपरी बांह को स्थिर रखते हुए सांस छोड़ें और डंबल को अपने कंधे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1738', 'Dumbbell Seated Reverse Grip One Arm Overhead Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","डम्बल को हाथ से पकड़ें और अपने हाथ को सीधा ऊपर की ओर फैलाएँ।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपनी कोहनी को मोड़कर डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर अपने हाथ को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0405', 'Dumbbell Seated Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर अपनी जाँघों पर आराम करते हुए एक बेंच पर बैठें।","डम्बल को कंधे की ऊँचाई तक उठाएँ, हथेलियाँ आगे की ओर हों।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक कि आपकी बाहें पूरी तरह से ऊपर की ओर न फैल जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस कंधे की ऊंचाई तक ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0404', 'Dumbbell Seated Shoulder Press (Parallel Grip)', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, palms facing inward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ अंदर की ओर हों।","डम्बल को कंधे की ऊँचाई तक उठाएँ, कोहनियाँ मुड़ी हुई हों और हथेलियाँ आगे की ओर हों।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक कि आपकी बाहें पूरी तरह से ऊपर की ओर न फैल जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस कंधे की ऊंचाई तक ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2188', 'Dumbbell Seated Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up overhead.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Pause for a moment, then straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","दोनों हाथों से डम्बल पकड़ें और अपनी भुजाओं को सीधा ऊपर की ओर फैलाएँ।","अपनी कोहनियों को मोड़ें और डम्बल को अपने सिर के पीछे नीचे करें, अपनी ऊपरी भुजाओं को अपने कानों के पास रखें।","एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0406', 'Dumbbell Shrug', 'back', 'traps', '["shoulders"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Keep your arms straight and let the dumbbells hang by your sides.","Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.","Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में डंबल पकड़ लें।","अपनी भुजाओं को सीधा रखें और डम्बल को अपने बगल में लटका दें।","अपने कंधों को जितना संभव हो उतना ऊपर उठाएं, जैसे कि आप अपने कंधों से अपने कानों को छूने की कोशिश कर रहे हों।","एक सेकंड के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Shrug/0.jpg","Dumbbell_Shrug/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0407', 'Dumbbell Side Bend', 'waist', 'abs', '["obliques"]', 'dumbbell', 'strength', 'beginner', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर सीधे खड़े हो जाएं और एक हाथ में डंबल पकड़ लें, जिससे वह आपकी बगल में लटक जाए।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, धीरे-धीरे कमर को डंबल के विपरीत दिशा की ओर झुकाएं, जितना आप आराम से कर सकते हैं उतना वजन कम करें।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें और दोहराएं।"]', '["Dumbbell_Side_Bend/0.jpg","Dumbbell_Side_Bend/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0408', 'Dumbbell Side Lying One Hand Raise', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Lie on your side with your legs extended and your head supported by your arm.","Hold a dumbbell in your top hand with your palm facing down.","Keeping your arm straight, raise the dumbbell up to shoulder height.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को फैलाकर और अपने सिर को अपनी बांह के सहारे रखते हुए अपनी तरफ लेटें।","अपनी हथेली को नीचे की ओर रखते हुए अपने ऊपरी हाथ में डम्बल पकड़ें।","अपने हाथ को सीधा रखते हुए डंबल को कंधे की ऊंचाई तक उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3664', 'Dumbbell Side Plank With Rear Fly', 'back', 'upper back', '["shoulders","core"]', 'dumbbell', 'strength', NULL, '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को फैलाकर और एक दूसरे के ऊपर रखकर अपनी तरफ लेटकर शुरुआत करें।","अपनी कोहनी को 90 डिग्री के कोण पर मोड़ते हुए अपने अग्रबाहु को सीधे अपने कंधे के नीचे जमीन पर रखें।","अपने ऊपरी हाथ में डम्बल पकड़ें, अपनी बांह को सीधा नीचे जमीन की ओर फैलाकर रखें।","अपने कोर को संलग्न करें और अपने कूल्हों को जमीन से ऊपर उठाएं, जिससे आपके सिर से आपकी एड़ी तक एक सीधी रेखा बन जाए।","साइड प्लैंक स्थिति को बनाए रखते हुए, अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए डंबल को छत की ओर उठाएं।","डम्बल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3548', 'Dumbbell Single Arm Overhead Carry', 'shoulders', 'delts', '["traps","core"]', 'dumbbell', 'strength', NULL, '["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Continue walking for the desired distance or time.","Switch hands and repeat the exercise."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, एक हाथ में डम्बल पकड़कर सीधे खड़े हो जाएं।","अपनी बांह को पूरी तरह फैलाते हुए डम्बल को ऊपर उठाएं।","जब आप आगे बढ़ें तो अपने कोर को व्यस्त रखें और अपनी पीठ को सीधा रखें, डम्बल को सिर के ऊपर बनाए रखें।","वांछित दूरी या समय तक चलते रहें।","हाथ बदलें और व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0409', 'Dumbbell Single Leg Calf Raise', 'lower legs', 'calves', '["ankles"]', 'dumbbell', 'strength', NULL, '["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.","Hold a dumbbell in one hand and place your other hand on a wall or railing for support.","Raise your heel as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down below the step.","Repeat for the desired number of repetitions, then switch to the other leg."]', '["किसी सीढ़ी या मंच के किनारे पर अपनी एड़ियाँ लटकाकर और अपने पैर की उंगलियों को सीढ़ी पर रखकर खड़े हो जाएँ।","एक हाथ में डम्बल पकड़ें और अपने दूसरे हाथ को सहारे के लिए दीवार या रेलिंग पर रखें।","अपनी एड़ी को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर को अपने पैर की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस सीढ़ी के नीचे ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ, फिर दूसरे चरण पर जाएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1757', 'Dumbbell Single Leg Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Shift your weight onto your left leg and lift your right foot slightly off the ground.","Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Lower the dumbbell until your torso and right leg are parallel to the ground.","Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े रहें, अपने दाहिने हाथ में डम्बल पकड़ें।","अपना वजन अपने बाएं पैर पर डालें और अपने दाहिने पैर को जमीन से थोड़ा ऊपर उठाएं।","अपनी पीठ सीधी रखते हुए, कूल्हों पर आगे की ओर झुकें और डम्बल को ज़मीन की ओर झुकाएँ।","साथ ही, अपने दाहिने पैर को अपने पीछे सीधा फैलाएं, अपने बाएं घुटने को थोड़ा मोड़ते हुए।","डम्बल को तब तक नीचे करें जब तक आपका धड़ और दाहिना पैर जमीन के समानांतर न हो जाए।","एक पल के लिए रुकें, फिर शुरुआती स्थिति में लौटने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2805', 'Dumbbell Single Leg Deadlift With Stepbox Support', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Place your left foot on a stepbox or elevated surface behind you.","Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े रहें, अपने दाहिने हाथ में डम्बल पकड़ें।","अपने बाएँ पैर को अपने पीछे किसी स्टेपबॉक्स या ऊँची सतह पर रखें।","अपनी पीठ को सीधा और मुख्य भाग को व्यस्त रखते हुए, कूल्हों पर आगे की ओर झुकें, डम्बल को ज़मीन की ओर झुकाएँ।","जैसे ही आप डम्बल को नीचे करते हैं, उसी समय अपने बाएं पैर को अपने पीछे उठाएं, सिर से एड़ी तक एक सीधी रेखा बनाए रखें।","जब तक आप अपनी दाहिनी हैमस्ट्रिंग में खिंचाव महसूस न करें तब तक डम्बल को नीचे रखें, फिर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0410', 'Dumbbell Single Leg Split Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","एक पैर के साथ एक कदम आगे बढ़ाएं और अपने पैरों को इस तरह रखें कि आपका अगला पैर जमीन पर सपाट हो और आपका पिछला पैर एक बेंच या सीढ़ी पर ऊंचा हो।","अपने सामने के घुटने और कूल्हे को मोड़कर अपने शरीर को नीचे लाएँ, अपने पिछले घुटने को थोड़ा मोड़ें और अपनी पिछली एड़ी को ज़मीन से ऊपर रखें।","जब तक आपकी अगली जांघ ज़मीन के समानांतर न हो जाए, तब तक नीचे उतरना जारी रखें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी सामने की एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0411', 'Dumbbell Single Leg Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Extend one leg forward and keep it off the ground throughout the exercise.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Pause for a moment at the bottom, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","पूरे अभ्यास के दौरान एक पैर को आगे बढ़ाएं और इसे जमीन से ऊपर रखें।","अपने खड़े पैर को मोड़ें और अपने शरीर को नीचे नीचे करें जैसे कि कुर्सी पर पीछे बैठे हों।","अपनी छाती ऊपर और पीठ सीधी रखें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0413', 'Dumbbell Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों में एक-एक डंबल पकड़ लें।","अपनी छाती को ऊपर और मुख्य भाग को ऊपर रखते हुए, घुटनों और कूल्हों पर झुकते हुए अपने शरीर को नीचे करें, जैसे कि कुर्सी पर वापस बैठे हों।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Squat/0.jpg","Dumbbell_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3560', 'Dumbbell Standing Alternate Hammer Curl And Press', 'upper arms', 'biceps', '["forearms","shoulders"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your back straight.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with your left hand.","After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Extend your arm fully and hold for a moment at the top.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the press with your left hand.","Continue alternating between curls and presses for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों।","अपनी कोहनियों को अपने धड़ के पास और अपनी पीठ को सीधा रखें।","साँस छोड़ें और अपने दाहिने हाथ में डम्बल को अपने कंधे की ओर मोड़ें, अपनी ऊपरी भुजा को स्थिर रखें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","अपने बाएं हाथ से कर्ल को दोहराएं।","अपने बाएं हाथ से कर्ल पूरा करने के बाद, सांस छोड़ें और अपने दाहिने हाथ में डंबल को ऊपर की ओर दबाएं।","अपना हाथ पूरी तरह फैलाएं और एक क्षण के लिए शीर्ष पर रुकें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","अपने बाएं हाथ से प्रेस को दोहराएं।","दोहराव की वांछित संख्या के लिए कर्ल और प्रेस के बीच बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0414', 'Dumbbell Standing Alternate Overhead Press', 'shoulders', 'delts', '["triceps","core"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press one dumbbell overhead, fully extending your arm.","Lower the dumbbell back to shoulder level.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में कंधे के स्तर पर डंबल पकड़ें।","अपनी बांह को पूरी तरह फैलाते हुए एक डम्बल को ऊपर की ओर दबाएं।","डम्बल को वापस कंधे के स्तर तक नीचे लाएँ।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0415', 'Dumbbell Standing Alternate Raise', 'shoulders', 'delts', '["traps","forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and your core engaged.","Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें और अपनी हथेलियों को अपने शरीर की ओर रखें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","एक डंबल को साइड में उठाएं, अपनी बांह सीधी रखें और अपनी हथेली नीचे की ओर रखें।","तब तक उठाना जारी रखें जब तक आपकी भुजा जमीन के समानांतर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं के बीच वैकल्पिक करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1739', 'Dumbbell Standing Alternating Tricep Kickback', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, keeping your elbows close to your body.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat with the other arm, alternating sides with each repetition."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपनी भुजाओं को पीछे की ओर सीधा फैलाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","प्रत्येक पुनरावृत्ति के साथ पक्षों को बदलते हुए, दूसरे हाथ से दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2143', 'Dumbbell Standing Around World', 'shoulders', 'delts', '["triceps","forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Extend your arms straight out to the sides at shoulder height, palms facing down.","Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Continue the circular motion, bringing the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपनी भुजाओं को कंधे की ऊंचाई पर बगल की ओर सीधा फैलाएं, हथेलियाँ नीचे की ओर हों।","अपनी भुजाओं को सीधा रखते हुए, धीरे-धीरे अपनी भुजाओं को गोलाकार गति में घुमाएँ, डम्बल को अपने शरीर के सामने और फिर ऊपर की ओर लाएँ।","डम्बल को प्रारंभिक स्थिति में वापस लाते हुए गोलाकार गति जारी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1740', 'Dumbbell Standing Bent Over One Arm Triceps Extension', 'upper arms', 'triceps', '["shoulders","back"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें।","अपनी पीठ को सीधा और जमीन के समानांतर रखते हुए कमर के बल आगे की ओर झुकें।","अपनी कोहनी को अपने शरीर के पास रखते हुए, अपना हाथ सीधा पीछे की ओर फैलाएँ।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', '["Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg","Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1741', 'Dumbbell Standing Bent Over Two Arm Triceps Extension', 'upper arms', 'triceps', '["shoulders","back"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Extend your arms straight back, keeping your elbows close to your body.","Slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपनी पीठ सीधी और घुटने थोड़े मुड़े हुए रखते हुए कमर के बल आगे की ओर झुकें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपनी भुजाओं को पीछे की ओर सीधा फैलाएँ।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg","Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0416', 'Dumbbell Standing Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आगे की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0417', 'Dumbbell Standing Calf Raise', 'lower legs', 'calves', '["ankles"]', 'dumbbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","अपनी पिंडलियों का उपयोग करते हुए अपनी एड़ियों को जमीन से जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Dumbbell_Calf_Raise/0.jpg","Standing_Dumbbell_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0418', 'Dumbbell Standing Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.","Place your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें, आपका हाथ पूरी तरह फैला हुआ हो और हथेली अंदर की ओर हो।","समर्थन के लिए अपने उल्टे हाथ को अपनी जांघ पर रखें।","अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0419', 'Dumbbell Standing Front Raise Above Head', 'shoulders', 'delts', '["trapezius","biceps"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी बाहों को सीधा रखें और डम्बल को अपने सामने उठाएं, उन्हें अपने सिर के ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2321', 'Dumbbell Standing Inner Biceps Curl v. 2', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","While holding your upper arms stationary, curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपने हाथों की हथेलियों को तब तक घुमाएँ जब तक वे आगे की ओर न आ जाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","सांस अंदर लेते हुए धीरे-धीरे डम्बल को शुरुआती स्थिति में वापस लाना शुरू करें।","दोहराव की अनुशंसित मात्रा के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0420', 'Dumbbell Standing Kickback', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी भुजाओं को पीछे की ओर सीधा फैलाएँ, अपनी ट्राइसेप्स को गति के शीर्ष पर दबाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0421', 'Dumbbell Standing One Arm Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Place your free hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और एक हाथ में डंबल पकड़ लें, हथेली ऊपर की ओर रखें।","समर्थन के लिए अपने खाली हाथ को अपनी जांघ पर रखें।","अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0422', 'Dumbbell Standing One Arm Curl (Over Incline Bench)', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में डंबल पकड़ें और अपनी हथेली आगे की ओर रखें।","समर्थन के लिए अपने दूसरे हाथ को झुकी हुई बेंच पर रखें।","अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', '["Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg","Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1680', 'Dumbbell Standing One Arm Curl Over Incline Bench', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें।","समर्थन के लिए अपने दूसरे हाथ को झुकी हुई बेंच पर रखें।","अपनी ऊपरी बांह को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', '["Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg","Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0423', 'Dumbbell Standing One Arm Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Keep your upper arm close to your head and perpendicular to the ground.","Slowly lower the dumbbell behind your head, bending your elbow.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें।","अपनी बांह को पूरी तरह फैलाते हुए डम्बल को ऊपर उठाएं।","अपनी ऊपरी भुजा को अपने सिर के पास और ज़मीन से सीधा रखें।","अपनी कोहनी को मोड़ते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0424', 'Dumbbell Standing One Arm Palm In Press', 'shoulders', 'delts', '["triceps","core"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Engage your core and keep your back straight.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में कंधे की ऊंचाई पर डंबल पकड़ें और अपनी हथेली अंदर की ओर रखें।","अपने कोर को व्यस्त रखें और अपनी पीठ सीधी रखें।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपका हाथ पूरी तरह फैल न जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', '["Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg","Standing_Palm-In_One-Arm_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0425', 'Dumbbell Standing One Arm Reverse Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Keep your arm fully extended and close to your body, with your palm facing down.","Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और एक हाथ में डंबल को ओवरहैंड ग्रिप से पकड़ लें।","अपनी बांह को पूरी तरह फैलाकर अपने शरीर के करीब रखें, आपकी हथेली नीचे की ओर हो।","अपनी ऊपरी भुजा को स्थिर रखते हुए धीरे-धीरे डम्बल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0426', 'Dumbbell Standing Overhead Press', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में कंधे के स्तर पर डंबल पकड़ें।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक कि आपकी बाहें पूरी तरह से ऊपर की ओर न फैल जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0427', 'Dumbbell Standing Palms In Press', 'shoulders', 'delts', '["triceps","chest"]', 'dumbbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे के स्तर पर डंबल पकड़ें और हथेलियां अंदर की ओर हों।","अपने कोर को व्यस्त रखते हुए और अपनी पीठ को सीधा रखते हुए, डंबल को ऊपर की ओर तब तक दबाएं जब तक कि आपकी भुजाएं पूरी तरह से ऊपर की ओर न फैल जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Palms-In_Dumbbell_Press/0.jpg","Standing_Palms-In_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0428', 'Dumbbell Standing Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और दोनों हाथों में डंबल पकड़ लें, हथेलियां आगे की ओर हों।","अपनी ऊपरी बांहों के पिछले हिस्से को उपदेशक बेंच या झुकी हुई बेंच पर टिकाएं, अपनी कोहनियों को थोड़ा मोड़कर।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0429', 'Dumbbell Standing Reverse Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'intermediate', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए सीधे खड़े हो जाएं और प्रत्येक हाथ में डम्बल पकड़ें, हथेलियाँ आपके शरीर की ओर हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें। जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Dumbbell_Reverse_Curl/0.jpg","Standing_Dumbbell_Reverse_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0430', 'Dumbbell Standing Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Raise the dumbbell overhead, keeping your arm straight.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Extend your arm back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें।","अपनी बांह सीधी रखते हुए डम्बल को ऊपर उठाएं।","अपनी कोहनी मोड़ें और अपने ऊपरी बांह को स्थिर रखते हुए डंबल को अपने सिर के पीछे नीचे करें।","अपने हाथ को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Dumbbell_Triceps_Extension/0.jpg","Standing_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-2293', 'Dumbbell Standing Zottman Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing forward.","Place your upper arms against the preacher bench and keep your elbows slightly bent.","Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing downward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आगे की ओर हों।","अपनी ऊपरी भुजाओं को उपदेशक बेंच के सामने रखें और अपनी कोहनियों को थोड़ा मोड़कर रखें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए डम्बल को अपने कंधों की ओर मोड़ें।","आंदोलन के शीर्ष पर, अपनी कलाइयों को घुमाएं ताकि आपकी हथेलियां नीचे की ओर हों।","धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ, साथ ही अपनी कलाइयों को भी प्रारंभिक स्थिति में घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1684', 'Dumbbell Step Up Single Leg Balance With Bicep Curl', 'upper arms', 'biceps', '["quadriceps","glutes","hamstrings"]', 'dumbbell', 'strength', NULL, '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Continue alternating sides for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ आपके शरीर की ओर रखते हुए, किसी सीढ़ी या मंच के सामने खड़े हो जाएँ।","अपने दाहिने पैर को सीढ़ी पर रखें, यह सुनिश्चित करते हुए कि आपका पूरा पैर सतह के संपर्क में है।","अपने कोर को संलग्न करें और अपने शरीर को सीढ़ी पर ऊपर उठाने के लिए अपनी दाहिनी एड़ी के माध्यम से धक्का दें, अपने बाएं घुटने को अपनी छाती की ओर लाएं।","मूवमेंट के शीर्ष पर, अपनी कोहनियों को मोड़कर और डम्बल को अपने कंधों की ओर लाकर बाइसेप कर्ल करें।","डम्बल को वापस नीचे करें और साथ ही अपने बाएँ पैर को भी वापस ज़मीन पर टिकाएँ।","इस क्रिया को विपरीत दिशा में दोहराएं, अपने बाएं पैर को ऊपर उठाएं और डम्बल को मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0431', 'Dumbbell Step-Up', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', 'intermediate', '["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Bring your left foot up onto the bench or step, standing fully upright.","Step back down with your left foot, followed by your right foot, returning to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच या कदम के सामने खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों।","अपने दाहिने पैर को बेंच या सीढ़ी पर रखें, यह सुनिश्चित करते हुए कि आपका पूरा पैर सतह के संपर्क में है।","अपनी दाहिनी एड़ी को धक्का दें और अपने दाहिने पैर को सीधा करते हुए अपने शरीर को बेंच या सीढ़ी पर ऊपर उठाएं।","पूरी तरह सीधे खड़े होकर अपने बाएँ पैर को बेंच या सीढ़ी पर ऊपर लाएँ।","अपने बाएँ पैर से नीचे आएँ, उसके बाद अपने दाएँ पैर से, प्रारंभिक स्थिति में लौट आएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', '["Dumbbell_Step_Ups/0.jpg","Dumbbell_Step_Ups/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2796', 'Dumbbell Step-Up Lunge', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Place your right foot on the step, ensuring your entire foot is on the surface.","Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Repeat the movement, alternating which foot you step up with each time.","Continue for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक सीढ़ी या मंच के सामने खड़े हो जाएं, हथेलियाँ आपके बगल की ओर हों।","अपने दाहिने पैर को सीढ़ी पर रखें, यह सुनिश्चित करते हुए कि आपका पूरा पैर सतह पर है।","अपनी दाहिनी एड़ी को धक्का दें और अपने शरीर को सीढ़ी पर ऊपर उठाएं, अपने बाएं पैर को भी ऊपर लाएं।","एक बार जब दोनों पैर सीढ़ी पर आ जाएँ, तो अपने बाएँ पैर को वापस प्रारंभिक स्थिति में ले आएँ, अपने दाहिने पैर को सीढ़ी पर रखें।","हर बार आप जिस पैर से ऊपर उठ रहे हैं, उसे बारी-बारी से दोहराएँ।","दोहराव की वांछित संख्या के लिए जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2812', 'Dumbbell Step-Up Split Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","As you step up, simultaneously lift your left knee towards your chest.","Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Repeat the movement with your left foot on the bench or step.","Continue alternating between your right and left foot for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच या कदम के सामने खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों।","अपने दाहिने पैर को बेंच या सीढ़ी पर रखें, यह सुनिश्चित करते हुए कि आपका पूरा पैर सतह के संपर्क में है।","बेंच पर चढ़ें या अपने शरीर को ऊपर उठाने के लिए अपनी एड़ी से दबाव डालते हुए अपने दाहिने पैर से आगे बढ़ें।","जैसे ही आप आगे बढ़ते हैं, साथ ही अपने बाएं घुटने को अपनी छाती की ओर उठाएं।","आंदोलन के शीर्ष पर रुकें, फिर अपने दाहिने पैर को बेंच या सीढ़ी पर रखते हुए धीरे-धीरे अपने बाएं पैर को वापस जमीन पर लाएं।","अपने बाएं पैर को बेंच या सीढ़ी पर रखकर इस क्रिया को दोहराएं।","दोहराव की वांछित संख्या के लिए अपने दाएं और बाएं पैर के बीच बारी-बारी से व्यायाम करना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0432', 'Dumbbell Stiff Leg Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.","Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी पीठ को सीधा और अपने कोर को व्यस्त रखते हुए, कूल्हों पर टिकाएं और डम्बल को जमीन की ओर नीचे करें, जिससे आपके घुटनों में हल्का सा मोड़ आ जाए।","जब तक आप अपनी हैमस्ट्रिंग में खिंचाव महसूस न करें तब तक डम्बल को नीचे रखें, फिर अपने ग्लूट्स को निचोड़ें और प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0433', 'Dumbbell Straight Arm Pullover', 'chest', 'pectorals', '["latissimus dorsi","triceps"]', 'dumbbell', 'strength', 'intermediate', '["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने सिर को एक छोर पर रखकर सीधे लेट जाएं और आपके पैर जमीन पर मजबूती से टिके हों।","दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए, धीरे-धीरे डम्बल को अपने सिर के पीछे एक चाप जैसी गति में नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Straight-Arm_Dumbbell_Pullover/0.jpg","Straight-Arm_Dumbbell_Pullover/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0434', 'Dumbbell Straight Leg Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए, कूल्हों पर टिकाएं और डम्बल को जमीन की ओर झुकाएं, जिससे आपका धड़ आगे की ओर झुक जाए।","जब तक आप अपने हैमस्ट्रिंग में खिंचाव महसूस न करें, तब तक डम्बल को नीचे करना जारी रखें, अपने घुटनों को थोड़ा मोड़कर रखें।","नीचे एक पल के लिए रुकें, फिर अपने धड़ को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2808', 'Dumbbell Sumo Pull Through', 'upper legs', 'glutes', '["hamstrings","quadriceps","core"]', 'dumbbell', 'strength', NULL, '["Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Hold a dumbbell with both hands in front of your body, arms extended.","Bend your knees and lower your hips down into a squat position, keeping your back straight.","Lower the dumbbell down between your legs, keeping your arms straight.","Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां बाहर की ओर हों।","अपने शरीर के सामने दोनों हाथों से डम्बल पकड़ें, बाहें फैली हुई।","अपने घुटनों को मोड़ें और अपनी पीठ को सीधा रखते हुए अपने कूल्हों को स्क्वाट स्थिति में नीचे लाएँ।","अपनी बाहों को सीधा रखते हुए डम्बल को अपने पैरों के बीच नीचे रखें।","अपनी एड़ी के माध्यम से ड्राइव करें और अपने कूल्हों को आगे बढ़ाएं, डम्बल को ऊपर और अपने शरीर के सामने खींचें।","आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ें, फिर डम्बल को वापस अपने पैरों के बीच नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2803', 'Dumbbell Supported Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों में एक-एक डंबल पकड़ लें।","अपनी छाती को ऊपर और कोर को व्यस्त रखते हुए, अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए धीरे-धीरे अपने शरीर को नीचे लाएँ।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0436', 'Dumbbell Tate Press', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a flat bench with a dumbbell in each hand, palms facing each other.","Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.","Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.","Rotate your wrists back to the starting position and repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, एक सपाट बेंच पर बैठें।","डम्बल को कंधे की ऊंचाई तक उठाएं, फिर अपनी कलाइयों को घुमाएं ताकि आपकी हथेलियां आपसे दूर रहें।","डम्बल को तब तक ऊपर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ, फिर उन्हें वापस कंधे की ऊँचाई तक नीचे लाएँ।","अपनी कलाइयों को वापस प्रारंभिक स्थिति में घुमाएँ और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1742', 'Dumbbell Tricep Kickback With Stork Stance', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी दाहिनी कोहनी को 90 डिग्री के कोण पर मोड़ते हुए अपनी तरफ ऊपर लाएँ।","अपने ट्राइसेप्स को निचोड़ते हुए अपने दाहिने हाथ को सीधा पीछे की ओर फैलाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1743', 'Dumbbell Twisting Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbells down towards your chest, keeping your elbows close to your body.","As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ आपसे दूर की ओर हों।","अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, डम्बल को अपनी छाती की ओर नीचे करें।","जैसे ही आप डम्बल को नीचे करते हैं, अपनी कलाइयों को मोड़ें ताकि आंदोलन के निचले भाग में आपकी हथेलियाँ आपकी ओर हों।","नीचे एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में दबाकर गति को उलट दें।","जैसे ही आप डम्बल को ऊपर दबाते हैं, अपनी कलाइयों को वापस शुरुआती स्थिति में मोड़ें और हथेलियाँ आपसे दूर रहें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0437', 'Dumbbell Upright Row', 'shoulders', 'delts', '["traps","biceps"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर डम्बल को अपनी जांघों के सामने लटका रहने दें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, सांस छोड़ें और डम्बल को अपनी कोहनियों की ओर ले जाते हुए सीधे अपनी ठुड्डी की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1765', 'Dumbbell Upright Row (Back Pov)', 'shoulders', 'delts', '["traps","biceps"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","डम्बल को अपनी जाँघों के सामने लटका दें, आपकी भुजाएँ पूरी तरह फैली हुई हों और आपकी हथेलियाँ आपके शरीर की ओर हों।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, सांस छोड़ें और डम्बल को अपनी कोहनियों की ओर ले जाते हुए सीधे अपनी ठुड्डी की ओर उठाएं।","तब तक उठाना जारी रखें जब तक कि डम्बल कंधे की ऊंचाई पर न आ जाएं, आपकी कोहनियां बगल की ओर हों।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0864', 'Dumbbell Upright Shoulder External Rotation', 'shoulders', 'delts', '["rotator cuff","trapezius"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में डंबल पकड़ लें।","अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक कि वे ज़मीन के समानांतर न हो जाएँ, अपनी कोहनियों को थोड़ा मुड़ा हुआ रखें।","अपनी भुजाओं को बाहर की ओर घुमाएँ, अपनी कोहनियों को उसी स्थिति में रखते हुए डम्बल को अपने सिर की ओर लाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-5201', 'Dumbbell Waiter Biceps Curl', 'upper arms', 'biceps', '["forearms","shoulders"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms close to your body and your elbows tucked in.","Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आगे की ओर हों।","अपनी ऊपरी भुजाओं को अपने शरीर के पास रखें और अपनी कोहनियों को अंदर की ओर रखें।","अपनी कलाइयों को सीधा रखते हुए धीरे-धीरे डम्बल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0438', 'Dumbbell W-Press', 'shoulders', 'delts', '["triceps","chest"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ आगे की ओर हों।","डम्बल को कंधे की ऊँचाई तक उठाएँ, कोहनियाँ मुड़ी हुई हों और हथेलियाँ आगे की ओर हों।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक कि आपकी बाहें पूरी तरह से ऊपर की ओर न फैल जाएँ।","डम्बल को वापस कंधे की ऊँचाई तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0439', 'Dumbbell Zottman Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and rotate your palms to face forward.","Curl the dumbbells up to your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing away from your body.","Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपनी हथेलियों को आगे की ओर घुमाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए डम्बल को अपने कंधों तक मोड़ें।","आंदोलन के शीर्ष पर, अपनी कलाइयों को घुमाएं ताकि आपकी हथेलियां आपके शरीर से दूर रहें।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएँ, अपनी हथेलियों को अपने शरीर की ओर घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2294', 'Dumbbell Zottman Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.","At the top of the curl, rotate your wrists so that your palms are facing down.","Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ ऊपर की ओर और कोहनियाँ पैड पर टिकाकर एक उपदेशक बेंच पर बैठें।","डम्बल को अपने कंधों की ओर मोड़ें, अपनी ऊपरी भुजाओं को स्थिर रखें और अपनी हथेलियों को ऊपर की ओर रखें।","कर्ल के शीर्ष पर, अपनी कलाइयों को घुमाएं ताकि आपकी हथेलियां नीचे की ओर हों।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं, ऐसा करते समय अपनी कलाइयों को वापस प्रारंभिक स्थिति में घुमाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2189', 'Dumbbells Seated Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Extend your arms and raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","दोनों हाथों में डंबल को ओवरहैंड ग्रिप से पकड़ें और इसे अपने सिर के ऊपर उठाएं।","अपनी कोहनियों को मोड़ें और डम्बल को अपने सिर के पीछे नीचे करें, अपनी ऊपरी भुजाओं को अपने कानों के पास रखें।","अपनी भुजाएँ फैलाएँ और डम्बल को वापस प्रारंभिक स्थिति में उठाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1167', 'Dynamic Chest Stretch (Male)', 'chest', 'pectorals', '["shoulders","triceps"]', 'body weight', 'strength', NULL, '["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े रहें।","अपनी भुजाओं को ज़मीन के समानांतर, भुजाओं तक सीधा फैलाएँ।","धीरे-धीरे अपनी भुजाओं को अपने शरीर के सामने क्रॉस करते हुए आगे लाएँ।","अपनी छाती की मांसपेशियों में खिंचाव महसूस करें।","10-30 सेकंड तक खिंचाव बनाए रखें।","प्रारंभिक स्थिति पर लौटें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3287', 'Elbow Dips', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["किसी बेंच या कुर्सी के किनारे पर अपने हाथों से अपने कूल्हों के बगल वाले किनारे को पकड़कर बैठें।","अपने कूल्हों को बेंच से आगे की ओर खिसकाएँ और अपनी एड़ियों को ज़मीन पर रखते हुए अपने पैरों को सीधा करें।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी पीठ को बेंच के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करने के लिए अपने हाथों से धक्का दें और अपने शरीर को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1772', 'Elbow Lift - Reverse Push-Up', 'back', 'upper back', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपने हाथों को सीधे अपने कंधों के नीचे रखकर जमीन पर मुंह के बल लेटकर शुरुआत करें।","अपने कोर को संलग्न करें और अपने ऊपरी शरीर को जमीन से ऊपर उठाने के लिए अपनी हथेलियों से दबाएं, अपनी कोहनियों को अपने किनारों के करीब रखें।","अपनी ऊपरी पीठ की मांसपेशियों को निचोड़ते हुए एक पल के लिए शीर्ष पर रुकें।","धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0443', 'Elbow-To-Knee', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', 'beginner', '["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए अपनी पीठ के बल लेटकर शुरुआत करें।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को संलग्न करें और अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, अपनी दाहिनी कोहनी को अपने बाएं घुटने की ओर लाएं।","साथ ही, घुमाने की गति बनाते हुए अपने बाएं घुटने को अपनी दाहिनी कोहनी की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को नीचे लाएं और अपने पैरों को वापस प्रारंभिक स्थिति में फैलाएं।","इस क्रिया को दोहराएँ, इस बार अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर और अपने दाहिने घुटने को अपनी बाईं कोहनी की ओर लाएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Elbow_to_Knee/0.jpg","Elbow_to_Knee/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-3292', 'Elevator', 'back', 'upper back', '["shoulders","trapezius"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपने हाथों को अपने कूल्हों पर रखें या उन्हें अपनी छाती के सामने क्रॉस करें।","अपनी पीठ को सीधा रखते हुए, धीरे-धीरे कमर के बल आगे की ओर झुकें, अपने ऊपरी शरीर को जमीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को प्रारंभिक स्थिति में वापस उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1332', 'Exercise Ball Alternating Arm Ups', 'back', 'lats', '["shoulders","core"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat the movement with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा करके बैठें।","अपनी हथेलियों को अंदर की ओर रखते हुए और अपनी भुजाओं को बगल में नीचे की ओर फैलाते हुए प्रत्येक हाथ में एक डम्बल पकड़ें।","अपने कोर को संलग्न करें और अपनी कोहनी को थोड़ा मोड़ते हुए धीरे-धीरे एक हाथ को अपने कंधे की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं।","दूसरे हाथ से भी यही क्रिया दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1333', 'Exercise Ball Back Extension With Arms Extended', 'back', 'spine', '["glutes","hamstrings"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Extend your arms straight out in front of you, with your palms facing down.","Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल को जमीन पर रखें और उसके ऊपर मुंह करके लेट जाएं, अपने कूल्हों को बॉल पर टिकाएं और स्थिरता के लिए अपने पैरों को दीवार पर टिकाएं।","अपनी हथेलियों को नीचे की ओर रखते हुए अपनी भुजाओं को अपने सामने सीधा फैलाएँ।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपनी पीठ सीधी रखें और अपनी गर्दन अपनी रीढ़ की हड्डी के अनुरूप रखें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1334', 'Exercise Ball Back Extension With Hands Behind Head', 'back', 'spine', '["glutes","hamstrings"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Position your feet against a wall or other stable surface for support.","Cross your arms behind your head, with your hands touching the back of your head.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल को जमीन पर रखें और अपने कूल्हों को बॉल पर टिकाकर उसके ऊपर मुंह करके लेट जाएं।","समर्थन के लिए अपने पैरों को दीवार या अन्य स्थिर सतह पर रखें।","अपनी बाहों को अपने सिर के पीछे क्रॉस करें, अपने हाथों को अपने सिर के पीछे छूते हुए।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपनी पीठ को तब तक फैलाएं जब तक कि आपका शरीर आपके सिर से आपके कूल्हों तक एक सीधी रेखा न बना ले।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1335', 'Exercise Ball Back Extension With Knees Off Ground', 'back', 'spine', '["glutes","hamstrings"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल को जमीन पर रखें और उसके ऊपर मुंह करके लेट जाएं, अपने कूल्हों को बॉल पर टिकाएं और स्थिरता के लिए अपने पैरों को दीवार पर टिकाएं।","अपने हाथों को अपने सिर के पीछे रखें या अपनी छाती के ऊपर रखें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपनी पीठ को तब तक फैलाएं जब तक कि आपका शरीर आपके सिर से आपकी एड़ी तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1336', 'Exercise Ball Back Extension With Rotation', 'back', 'spine', '["glutes","hamstrings"]', 'stability ball', 'strength', NULL, '["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Return to the center and repeat the rotation to the other side.","Lower your upper body back down to the starting position and repeat for the desired number of repetitions."]', '["अपने कूल्हों को गेंद पर टिकाकर और अपने पैरों को मजबूती से जमीन पर टिकाकर स्टेबिलिटी बॉल पर मुंह के बल लेटकर शुरुआत करें।","अपने हाथों को अपने सिर के पीछे रखें या उन्हें अपनी छाती के ऊपर से पार करें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपनी पीठ को तब तक फैलाएं जब तक कि आपका शरीर आपके सिर से आपकी एड़ी तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों और पैरों को स्थिर रखते हुए अपने धड़ को एक तरफ घुमाएं।","केंद्र पर लौटें और दूसरी ओर भी घुमाएँ।","अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1744', 'Exercise Ball Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the ball beside your hips, fingers pointing forward.","Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Lower your body back down by bending your elbows, keeping them close to your sides.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट करके बैठें और आपके घुटने 90 डिग्री के कोण पर मुड़े हों।","अपने हाथों को अपने कूल्हों के पास गेंद पर रखें, उंगलियां आगे की ओर हों।","अपने ट्राइसेप्स को संलग्न करें और अपने हाथों को सीधा करते हुए अपने शरीर को गेंद से ऊपर उठाने के लिए अपने हाथों से धक्का दें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को पीछे की ओर नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1559', 'Exercise Ball Hip Flexor Stretch', 'upper legs', 'glutes', '["quadriceps","hamstrings"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and kneel in front of it.","Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Extend your left leg behind you, keeping it straight.","Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["स्टेबिलिटी बॉल को ज़मीन पर रखें और उसके सामने घुटने टेकें।","अपने दाहिने पैर को स्टेबिलिटी बॉल के ऊपर रखें, अपने घुटने को 90 डिग्री के कोण पर मोड़ें।","अपने बाएँ पैर को सीधा रखते हुए अपने पीछे फैलाएँ।","अपने कूल्हों को स्टेबिलिटी बॉल की ओर धकेलते हुए आगे की ओर झुकें, जब तक कि आप अपने दाहिने कूल्हे के फ्लेक्सर में खिंचाव महसूस न करें।","20-30 सेकंड के लिए खिंचाव बनाए रखें, फिर किनारे बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1338', 'Exercise Ball Hug', 'back', 'spine', '["shoulders","chest"]', 'stability ball', 'strength', 'beginner', '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the stability ball with both hands, hugging it close to your chest.","Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Continue leaning back until you feel a stretch in your back muscles.","Hold the position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा करके बैठें।","स्टेबिलिटी बॉल को दोनों हाथों से पकड़ें, इसे अपनी छाती से सटाएं।","अपनी मुख्य मांसपेशियों को शामिल करें और धीरे-धीरे पीछे झुकें, अपनी पीठ सीधी रखें और अपने पैर ज़मीन पर रखें।","जब तक आप अपनी पीठ की मांसपेशियों में खिंचाव महसूस न करें तब तक पीछे झुकते रहें।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Hug_A_Ball/0.jpg","Hug_A_Ball/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1339', 'Exercise Ball Lat Stretch', 'back', 'lats', '["shoulders","triceps"]', 'stability ball', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up overhead.","Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक स्टेबिलिटी बॉल पर बैठें।","एक हाथ में डम्बल पकड़ें और अपने हाथ को सीधा ऊपर की ओर फैलाएँ।","अपनी लैट मांसपेशी में खिंचाव महसूस करते हुए धीरे-धीरे विपरीत दिशा में झुकें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1341', 'Exercise Ball Lower Back Stretch (Pyramid)', 'back', 'lats', '["glutes","hamstrings"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट करके बैठें और आपके घुटने 90 डिग्री के कोण पर मुड़े हों।","धीरे-धीरे अपने पैरों को आगे बढ़ाएं, गेंद को अपनी पीठ के नीचे तब तक घुमाएं जब तक कि आपकी निचली पीठ गेंद पर आराम न कर ले।","अपने हाथों को अपने सिर के पीछे रखें या उन्हें अपनी छाती के ऊपर से पार करें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को जमीन की ओर नीचे लाएं, जिससे आपकी पीठ के निचले हिस्से को गेंद के ऊपर फैलने का मौका मिले।","कुछ सेकंड के लिए खिंचाव बनाए रखें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1342', 'Exercise Ball Lying Side Lat Stretch', 'back', 'lats', '["shoulders","triceps"]', 'stability ball', 'strength', NULL, '["Lie on your side with your legs extended and your head supported by the stability ball.","Place your top arm on the ball for stability.","Reach your top arm overhead and allow your torso to rotate slightly.","Feel the stretch in your lat muscles on the side of your body.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["अपने पैरों को फैलाकर और अपने सिर को स्टेबिलिटी बॉल के सहारे रखकर करवट से लेटें।","स्थिरता के लिए अपनी ऊपरी भुजा को गेंद पर रखें।","अपनी ऊपरी भुजा को ऊपर की ओर ले जाएं और अपने धड़ को थोड़ा घूमने दें।","अपने शरीर के किनारे की अंडकोश की मांसपेशियों में खिंचाव महसूस करें।","20-30 सेकंड के लिए खिंचाव बनाए रखें, फिर किनारे बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1382', 'Exercise Ball On The Wall Calf Raise', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'dumbbell', 'strength', NULL, '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart, with your toes pointing forward.","Hold a dumbbell in each hand, with your arms extended by your sides.","Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ को दीवार से सटाकर खड़े हो जाएं और अपनी पीठ के निचले हिस्से और दीवार के बीच एक व्यायाम गेंद रखें।","अपने पैरों को कंधे की चौड़ाई से अलग रखें, आपके पैर की उंगलियां आगे की ओर हों।","प्रत्येक हाथ में एक डम्बल पकड़ें, अपनी भुजाएँ अपनी भुजाओं तक फैलाएँ।","अपनी एड़ियों को जमीन से ऊपर उठाएं, अपने शरीर का वजन अपने पैरों की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3241', 'Exercise Ball On The Wall Calf Raise (Tennis Ball Between Ankles)', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'dumbbell', 'strength', NULL, '["Stand facing a wall with your feet shoulder-width apart.","Place an exercise ball between the wall and your lower back.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your ankles.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए दीवार की ओर मुंह करके खड़े हो जाएं।","दीवार और अपनी पीठ के निचले हिस्से के बीच एक व्यायाम गेंद रखें।","प्रत्येक हाथ में एक डम्बल पकड़ें, अपनी भुजाएँ अपनी भुजाओं तक फैलाएँ।","अपनी एड़ियों के बीच एक टेनिस बॉल रखें।","अपनी एड़ियों को ज़मीन से ऊपर उठाएँ, अपने शरीर को अपने पंजों पर ऊपर उठाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3240', 'Exercise Ball On The Wall Calf Raise (Tennis Ball Between Knees)', 'lower legs', 'calves', '["quadriceps","hamstrings"]', 'dumbbell', 'strength', NULL, '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart and slightly in front of you.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your knees.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ को दीवार से सटाकर खड़े हो जाएं और अपनी पीठ के निचले हिस्से और दीवार के बीच एक व्यायाम गेंद रखें।","अपने पैरों को कंधे की चौड़ाई से अलग और थोड़ा अपने सामने रखें।","प्रत्येक हाथ में एक डम्बल पकड़ें, अपनी भुजाएँ अपनी भुजाओं तक फैलाएँ।","अपने घुटनों के बीच एक टेनिस बॉल रखें।","अपनी एड़ियों को ज़मीन से ऊपर उठाएँ, अपने शरीर को अपने पंजों पर ऊपर उठाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1416', 'Exercise Ball One Leg Prone Lower Body Rotation', 'upper legs', 'glutes', '["hamstrings","quadriceps","core"]', 'stability ball', 'strength', NULL, '["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for support.","Engage your glutes and core muscles to stabilize your body.","Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Repeat the rotation with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने कूल्हों को बॉल पर टिकाकर और अपने पैरों को सीधे अपने पीछे फैलाकर लेटें।","समर्थन के लिए अपने हाथों को अपने सामने ज़मीन पर रखें।","अपने शरीर को स्थिर करने के लिए अपने ग्लूट्स और कोर मांसपेशियों को शामिल करें।","धीरे-धीरे एक पैर को जमीन से ऊपर उठाएं, इसे सीधा और फर्श के समानांतर रखें।","अपने कूल्हों और ऊपरी शरीर को स्थिर रखते हुए, अपने पैर को अपने शरीर से दूर बाहर की ओर घुमाएँ।","घुमाव के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैर को प्रारंभिक स्थिति में लौटाएँ।","दूसरे पैर से भी घुमाव दोहराएं।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1417', 'Exercise Ball One Legged Diagonal Kick Hamstring Curl', 'upper legs', 'glutes', '["hamstrings","calves"]', 'stability ball', 'strength', NULL, '["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Place your arms by your sides for stability.","Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Slowly return your right leg to the starting position, maintaining control and stability.","Repeat the movement with your left leg, alternating sides for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी एड़ियों को स्टेबिलिटी बॉल के ऊपर रखकर अपनी पीठ के बल लेटकर शुरुआत करें।","स्थिरता के लिए अपनी भुजाओं को अपने बगल में रखें।","अपने कूल्हों को ज़मीन से ऊपर उठाने के लिए अपने ग्लूट्स और मुख्य मांसपेशियों को शामिल करें, जिससे आपके कंधों से आपकी एड़ी तक एक सीधी रेखा बन जाए।","अपने दाहिने घुटने को मोड़ें और इसे अपनी छाती की ओर लाएँ, अपने बाएँ पैर को फैलाए रखें और अपने पैर को लचीला रखें।","अपने दाहिने पैर को अपने शरीर पर तिरछे लात मारें, इसे पूरी तरह फैलाएं और अपनी हैमस्ट्रिंग को उलझाएं।","नियंत्रण और स्थिरता बनाए रखते हुए धीरे-धीरे अपने दाहिने पैर को प्रारंभिक स्थिति में लौटाएँ।","वांछित संख्या में दोहराव के लिए पक्षों को बदलते हुए, अपने बाएं पैर के साथ आंदोलन को दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1296', 'Exercise Ball Pike Push Up', 'chest', 'pectorals', '["shoulders","triceps","core"]', 'stability ball', 'strength', NULL, '["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Keep your legs straight and your body in a pike position, forming an inverted V shape.","Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को फर्श पर और अपनी पिंडलियों को स्टेबिलिटी बॉल पर टिकाकर पुश-अप स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने कूल्हों को छत की ओर उठाएं, गेंद को अपने हाथों की ओर घुमाएं।","अपने पैरों को सीधा रखें और अपने शरीर को उल्टे वी आकार बनाते हुए पाईक स्थिति में रखें।","अपनी कोहनियों को मोड़ें और अपने सिर को अपने हाथों की सीध में रखते हुए अपने ऊपरी शरीर को फर्श की ओर नीचे करें।","प्रारंभिक स्थिति में लौटने के लिए अपने हाथों से धक्का दें और अपनी भुजाओं को फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1343', 'Exercise Ball Prone Leg Raise', 'back', 'spine', '["abdominals","glutes"]', 'stability ball', 'strength', NULL, '["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक चटाई पर अपने पैरों को फैलाकर और अपने पैर की उंगलियों को स्टेबिलिटी बॉल के ऊपर रखकर लेट जाएं।","अपने हाथों को कंधे की चौड़ाई पर जमीन पर रखें और अपनी मुख्य मांसपेशियों को शामिल करें।","अपने पैरों को सीधा रखते हुए, धीरे-धीरे उन्हें जमीन से ऊपर उठाएं, अपनी पीठ के निचले हिस्से और ग्लूट्स का उपयोग करके उन्हें जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1560', 'Exercise Ball Seated Hamstring Stretch', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Place your hands on your hips for support.","Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट करके बैठें और आपके घुटने 90 डिग्री के कोण पर मुड़े हों।","गेंद को धीरे-धीरे आगे की ओर घुमाएँ, अपने पैरों को बाहर की ओर तब तक घुमाएँ जब तक कि आपकी पीठ का ऊपरी हिस्सा गेंद पर न टिक जाए और आपके पैर सीधे आपके सामने न फैल जाएँ।","समर्थन के लिए अपने हाथों को अपने कूल्हों पर रखें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को जमीन की ओर नीचे लाएं, अपनी पीठ सीधी रखें और अपनी छाती ऊपर उठाएं।","जब आप अपनी हैमस्ट्रिंग में खिंचाव महसूस करें तो रुकें और 20-30 सेकंड के लिए इसी स्थिति में रहें।","धीरे-धीरे अपनी एड़ियों से धक्का देकर और अपने हैमस्ट्रिंग का उपयोग करके अपने आप को वापस ऊपर खींचकर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1745', 'Exercise Ball Seated Triceps Stretch', 'upper arms', 'triceps', '["shoulders"]', 'stability ball', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Hold the stretch for a few seconds, then return to the starting position.","Repeat with the other arm."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक स्टेबिलिटी बॉल पर बैठें।","एक हाथ में डम्बल पकड़ें और अपने हाथ को सीधे अपने सिर के ऊपर फैलाएँ।","अपनी कोहनी मोड़ें और डम्बल को अपने सिर के पीछे नीचे करें, अपनी ऊपरी भुजा को अपने कान के पास रखें।","कुछ सेकंड के लिए खिंचाव को रोके रखें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरे हाथ से दोहराएँ."]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1746', 'Exercise Ball Supine Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक व्यायाम बॉल पर बैठें।","दोनों हाथों से डम्बल पकड़ें और अपनी भुजाओं को छत की ओर सीधा ऊपर उठाएं।","अपनी कोहनियों को अपने कानों के पास रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1747', 'Ez Bar French Press On Exercise Ball', 'upper arms', 'triceps', '["shoulders"]', 'ez barbell', 'strength', NULL, '["Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Extend your arms straight up, keeping your elbows close to your head.","Slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक एक्सरसाइज बॉल पर बैठें और ईज़ी बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी कोहनियों को अपने सिर के पास रखते हुए, अपनी बाहों को सीधा ऊपर फैलाएँ।","अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3010', 'Ez Bar Lying Bent Arms Pullover', 'back', 'lats', '["triceps","chest"]', 'ez barbell', 'strength', NULL, '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Extend your arms straight above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को फर्श पर रखकर सीधे लेट जाएं।","ईज़ी बारबेल को एक उभरी हुई पकड़ (हथेलियाँ आपसे दूर की ओर) और अपने हाथों को कंधे की चौड़ाई से अलग करके पकड़ें।","अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी कोहनियों में हल्का सा मोड़ बनाए रखते हुए बारबेल को अपने सिर के पीछे चाप की गति में नीचे लाएँ।","एक पल के लिए रुकें, फिर चाप की गति को उलट कर बारबेल को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1748', 'Ez Bar Lying Close Grip Triceps Extension Behind Head', 'upper arms', 'triceps', '["shoulders"]', 'ez barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","ईज़ बारबेल को कसकर पकड़ें, हथेलियाँ ऊपर की ओर हों, और अपनी भुजाओं को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1344', 'Ez Bar Reverse Grip Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'ez barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","ईज़ बारबेल को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और हाथ कंधे की चौड़ाई से अलग हों।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें, जब तक कि आपका धड़ लगभग फर्श के समानांतर न हो जाए।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, ईज़ बारबेल को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे ईज़ बारबेल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1682', 'Ez Bar Seated Close Grip Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Rest your elbow on the inside of your thigh, just above the knee.","Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को जमीन पर सपाट करके एक बेंच पर बैठें और ईज़ी बारबेल को हाथ से पकड़ें।","अपनी कोहनी को अपनी जांघ के अंदर, घुटने के ठीक ऊपर रखें।","अपने ऊपरी बांह को स्थिर रखते हुए बारबेल को अपने कंधे की ओर मोड़ें।","मूवमेंट के शीर्ष पर अपने बाइसेप्स को निचोड़ें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1749', 'Ez Bar Standing French Press', 'upper arms', 'triceps', '["shoulders"]', 'ez barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं और ईज़ बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को अपने सिर के ऊपर उठाएं।","अपनी ऊपरी भुजाओं को अपने सिर के पास रखते हुए, अपनी कोहनियों को मोड़कर बारबेल को धीरे-धीरे अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0445', 'Ez Barbell Anti Gravity Press', 'shoulders', 'delts', '["triceps","chest"]', 'ez barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.","Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर और ईज़ बारबेल को ओवरहैंड ग्रिप से पकड़कर शुरुआत करें।","बारबेल को कंधे की ऊंचाई तक उठाएं, अपनी कोहनियों को थोड़ा मोड़ें और अपनी हथेलियों को आगे की ओर रखें।","अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को ऊपर की ओर दबाएं।","बारबेल को वापस कंधे की ऊंचाई तक कम करें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1627', 'Ez Barbell Close Grip Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Slowly curl the barbell towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["प्रीचर कर्ल बेंच पर बैठें और अपनी ऊपरी भुजाओं को पैड पर रखें, ईज़ बारबेल को अंडरहैंड ग्रिप से पकड़ें।","अपने ट्राइसेप्स को पैड पर टिकाएं और अपनी पीठ को सीधा रखते हुए अपनी बाहों को पूरी तरह फैलाएं।","धीरे-धीरे अपने बाइसेप्स को सिकोड़ते हुए बारबेल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0446', 'Ez Barbell Close-Grip Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर सीधे खड़े हो जाएं और हाथों को कंधे की चौड़ाई की दूरी पर रखते हुए ईज़ बारबेल को हाथ से पकड़ें।","पूरे आंदोलन के दौरान अपनी कोहनियों को अपने धड़ के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने बाइसेप्स को सिकोड़ते हुए बारबेल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0447', 'Ez Barbell Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर सीधे खड़े हो जाएं और हथेलियों को ऊपर की ओर रखते हुए ईज़ बारबेल को हाथ से पकड़ें।","पूरे आंदोलन के दौरान अपनी कोहनियों को अपने धड़ के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","जैसे ही आप बारबेल को अपने कंधों की ओर मोड़ते हैं, अपने बाइसेप्स को सिकोड़ते हुए सांस छोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लेते हुए धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0448', 'Ez Barbell Decline Close Grip Face Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'ez barbell', 'strength', NULL, '["Lie on a decline bench with your head lower than your feet.","Grasp the ez barbell with a close grip, palms facing each other.","Extend your arms straight up above your chest, keeping your elbows close to your body.","Lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने पैरों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","ईज़ बारबेल को ज़ोर से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी कोहनियों को मोड़कर बारबेल को अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में दबाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2186', 'Ez Barbell Decline Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'ez barbell', 'strength', NULL, '["Lie on a decline bench with your head lower than your feet and your feet secured.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your head.","Lower the barbell slowly towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने पैरों से नीचे करके और अपने पैरों को सुरक्षित रखते हुए एक डिक्लाइन बेंच पर लेटें।","हाथों को कंधे की चौड़ाई से अलग रखते हुए ईज़ बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी कोहनियों को अपने सिर के पास रखते हुए, अपनी भुजाओं को पूरी तरह फैलाएँ।","अपनी कोहनियों को मोड़ते हुए बारबेल को धीरे-धीरे अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0449', 'Ez Barbell Incline Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'ez barbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","पैड के सामने अपनी पीठ रखकर बेंच पर बैठें और ईज़ बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी कोहनियों को अपने सिर के पास रखते हुए, अपनी भुजाओं को पूरी तरह ऊपर की ओर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर बारबेल को अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0450', 'Ez Barbell Jm Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'ez barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","ईज़ बारबेल को कंधे की चौड़ाई से थोड़ा चौड़ा ओवरहैंड ग्रिप से पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, बारबेल को अपनी छाती तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0451', 'Ez Barbell Reverse Grip Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Curl the barbell upwards by contracting your biceps, while exhaling.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the barbell back to the starting position as you inhale.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और ईज़ बारबेल को हाथ से पकड़ें।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपने धड़ के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ते हुए अपने बाइसेप्स को सिकोड़कर बारबेल को ऊपर की ओर मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","सांस लेते हुए धीरे-धीरे बारबेल को शुरुआती स्थिति में वापस लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0452', 'Ez Barbell Reverse Grip Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms on the pad, allowing your forearms to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक उपदेशक बेंच पर अपनी छाती को पैड से सटाकर और अपने पैरों को फर्श पर सपाट करके बैठें।","ईज़ बारबेल को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग।","अपनी ऊपरी भुजाओं को पैड पर टिकाएं, जिससे आपकी अग्रबाहुएं नीचे लटक जाएं।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और बारबेल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1458', 'Ez Barbell Seated Curls', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and your back straight.","Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा करके एक बेंच पर बैठें।","ईज़ बारबेल को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपनी ऊपरी भुजाओं को अपनी जाँघों पर टिकाएँ, जिससे ईज़ बारबेल आपके सामने लटक जाए।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और ईज़ बारबेल को अपने कंधों की ओर ऊपर की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे ईज़ बारबेल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0453', 'Ez Barbell Seated Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'ez barbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","हाथों को कंधे की चौड़ाई से अलग रखते हुए ईज़ बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को ऊपर उठाएं।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर बारबेल को अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर अपनी बाहों को फैलाकर बारबेल को शुरुआती स्थिति में वापस उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0454', 'Ez Barbell Spider Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियों को ऊपर की ओर रखते हुए ईज़ बारबेल को हाथ से पकड़ें।","अपनी ऊपरी भुजाओं को प्रीचर बेंच या स्टेबिलिटी बॉल पर रखें, जिससे आपकी कोहनियाँ नीचे लटक जाएँ।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और बारबेल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे बारबेल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1628', 'Ez Barbell Spider Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियों को ऊपर की ओर रखते हुए ईज़ बारबेल को हाथ से पकड़ें।","अपनी ऊपरी भुजाओं को प्रीचर बेंच या स्टेबिलिटी बॉल पर रखें, जिससे आपकी कोहनियाँ नीचे लटक जाएँ।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और बारबेल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे बारबेल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2404', 'Ez-Bar Biceps Curl (With Arm Blaster)', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर सीधे खड़े हो जाएं और हथेलियों को ऊपर की ओर रखते हुए ईज़ बारबेल को हाथ से पकड़ें।","अपनी ऊपरी भुजाओं को आर्म ब्लास्टर के सामने रखें और पूरे अभ्यास के दौरान उन्हें स्थिर रखें।","अपनी कोहनियों को अपने शरीर के पास रखते हुए सांस छोड़ें और बारबेल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2432', 'Ez-Bar Close-Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'ez barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","ईज़ बारबेल को ज़ोर से पकड़ें, हाथ कंधे की चौड़ाई पर अलग हों, हथेलियाँ आगे की ओर हों।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएं।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2741', 'Ez-Barbell Standing Wide Grip Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'ez barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए सीधे खड़े हो जाएं और ईज़ बारबेल को हाथ से पकड़ें, हाथ कंधे की चौड़ाई से अधिक चौड़े हों।","पूरे आंदोलन के दौरान अपनी कोहनियों को अपने धड़ के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने बाइसेप्स को सिकोड़कर बारबेल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2133', 'Farmers Walk', 'upper legs', 'quads', '["calves","forearms","core"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your sides.","Keep your back straight and your shoulders back.","Take small, controlled steps forward, maintaining an upright posture.","Continue walking for the desired distance or time.","To finish, stop walking and carefully lower the dumbbells to your sides."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके बगल की ओर हों।","अपनी पीठ सीधी और कंधे पीछे रखें।","सीधी मुद्रा बनाए रखते हुए छोटे, नियंत्रित कदम आगे बढ़ाएं।","वांछित दूरी या समय तक चलते रहें।","समाप्त करने के लिए, चलना बंद करें और डम्बल को सावधानी से अपनी तरफ नीचे करें।"]', NULL, 3.5, 'sets', 0, 'opengym', 1),
('og-0455', 'Finger Curls', 'lower arms', 'forearms', '["wrist flexors","grip muscles"]', 'barbell', 'strength', 'beginner', '["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your fingers towards your palms, squeezing the barbell tightly.","Hold the contraction for a moment, then slowly release your fingers back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को जमीन पर सपाट करके एक बेंच पर बैठें और हथेलियाँ ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","धीरे-धीरे अपनी उंगलियों को अपनी हथेलियों की ओर मोड़ें, बारबेल को कसकर दबाएं।","एक पल के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपनी उंगलियों को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Finger_Curls/0.jpg","Finger_Curls/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3303', 'Flag', 'waist', 'abs', '["obliques","shoulders"]', 'body weight', 'strength', NULL, '["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["दोनों हाथों से एक ऊर्ध्वाधर खंभे को पकड़ना शुरू करें, हथेलियाँ एक-दूसरे के सामने हों और भुजाएँ पूरी तरह फैली हुई हों।","अपने कोर को संलग्न करें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","अपनी कोर और ऊपरी शरीर की ताकत का उपयोग करते हुए, अपने पैरों को तब तक उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","शरीर की सीधी रेखा बनाए रखते हुए इस स्थिति में जितनी देर तक हो सके रुकें।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0456', 'Flexion Leg Sit Up (Bent Knee)', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","साथ ही, अपने पैरों को जमीन से ऊपर उठाएं, अपने घुटनों को मोड़ें और उन्हें अपनी छाती की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर और पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0457', 'Flexion Leg Sit Up (Straight Arm)', 'waist', 'abs', '["hip flexors","quadriceps"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और हाथों को अपने सिर के ऊपर सीधा रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने पेट को शामिल करते हुए, अपने ऊपरी शरीर को जमीन से ऊपर उठाएं और साथ ही अपने पैरों को अपनी छाती की ओर उठाएं।","अपने ऊपरी शरीर और पैरों को ऊपर उठाते हुए अपने हाथों को अपने पैर की उंगलियों तक ले जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर और पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0458', 'Floor Fly (With Barbell)', 'chest', 'pectorals', '["deltoids","triceps"]', 'barbell', 'strength', NULL, '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a barbell with an overhand grip, arms extended straight up over your chest.","Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए फर्श पर अपनी पीठ के बल लेट जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, बाहें सीधे आपकी छाती के ऊपर फैली हुई हों।","अपनी कोहनियों को हल्का सा मोड़ते हुए धीरे-धीरे बारबेल को किनारों से नीचे लाएँ।","बारबेल को तब तक नीचे रखें जब तक कि आपकी बाहें फर्श के समानांतर न हो जाएं, जिससे आपको अपनी छाती में खिंचाव महसूस हो।","एक पल के लिए रुकें, फिर बारबेल को प्रारंभिक स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0459', 'Flutter Kicks', 'upper legs', 'glutes', '["hip flexors","lower abs"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your legs extended and your hands by your sides.","Engage your core and lift your legs off the ground about 6 inches.","Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Continue this fluttering motion for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपने हाथों को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","अपने कोर को संलग्न करें और अपने पैरों को जमीन से लगभग 6 इंच ऊपर उठाएं।","अपने पैरों को सीधा रखते हुए बारी-बारी से एक पैर को दूसरे से थोड़ा ऊपर उठाएं।","दोहराव की वांछित संख्या के लिए इस फड़फड़ाहट गति को जारी रखें।"]', '["Flutter_Kicks/0.jpg","Flutter_Kicks/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1472', 'Forward Jump', 'upper legs', 'quads', '["calves","hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","गति के लिए अपनी भुजाओं को पीछे की ओर झुकाएँ।","अपने कूल्हों, घुटनों और टखनों को फैलाते हुए विस्फोटक तरीके से आगे बढ़ें।","अपने पैरों की उंगलियों पर धीरे से उतरें और तुरंत अगली छलांग लगाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3470', 'Forward Lunge (Male)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."]', '["अपने पैरों को कूल्हे की चौड़ाई पर और हाथों को अपने कूल्हों पर रखकर खड़े हो जाएं।","अपने दाहिने पैर के साथ एक बड़ा कदम आगे बढ़ाएं, अपने शरीर को लूंज स्थिति में नीचे लाएं।","अपने दाहिने घुटने को लगभग 90 डिग्री तक मोड़ें, अपने घुटने को अपने टखने के साथ संरेखित रखें।","अपने दाहिने पैर से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","वांछित संख्या में दोहराव के लिए पक्षों को बदलते हुए, अपने बाएं पैर से दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3194', 'Frankenstein Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.","Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और सीधी भुजाओं से बारबेल को अपने शरीर के सामने पकड़ें।","अपनी पीठ सीधी रखते हुए, घुटनों और कूल्हों पर झुकते हुए अपने शरीर को नीचे लाएँ, जैसे कि किसी कुर्सी पर पीछे बैठे हों।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Frankenstein_Squat/0.jpg","Frankenstein_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2429', 'Frog Crunch', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, अपने ऊपरी शरीर को ज़मीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3301', 'Frog Planche', 'waist', 'abs', '["shoulders","chest","triceps"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई पर और अपने पैरों को एक साथ मिलाकर पुश-अप स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़ें और अपनी पीठ को सीधा रखते हुए अपने शरीर को जमीन की ओर नीचे करें।","जैसे ही आप अपने शरीर को नीचे लाते हैं, अपने पैरों को ज़मीन से ऊपर उठाएं और अपने घुटनों को अपनी छाती की ओर लाएँ।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर अपने पैरों को पीछे की ओर फैलाएं और अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3296', 'Front Lever', 'waist', 'abs', '["lats","shoulders","forearms"]', 'body weight', 'strength', NULL, '["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."]', '["हाथों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार से ओवरहैंड पकड़ के साथ लटककर शुरुआत करें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को नीचे और पीछे खींचें।","अपने घुटनों को मोड़ें और उन्हें अपनी छाती की ओर मोड़ें।","इसके साथ ही, अपने पैरों को ऊपर उठाएं और अपने शरीर को जमीन के समानांतर रखते हुए उन्हें अपने सामने सीधा फैलाएं।","जब तक आप कर सकते हैं तब तक इस स्थिति में रहें, पूर्ण फ्रंट लीवर स्थिति का लक्ष्य रखें।","रिलीज़ करने के लिए, धीरे-धीरे अपने पैरों को वापस नीचे लाएँ और प्रारंभिक स्थिति में वापस आ जाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3295', 'Front Lever Reps', 'back', 'upper back', '["core","shoulders"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["पुल-अप बार से ओवरहैंड ग्रिप के साथ लटकें, हथेलियाँ आपसे दूर की ओर हों।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को नीचे और पीछे खींचें।","अपने शरीर को सीधा रखते हुए, अपने पैरों को ऊपर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","जब तक आप कर सकते हैं इस स्थिति में रहें, 10-20 सेकंड का लक्ष्य रखें।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0464', 'Front Plank With Twist', 'waist', 'abs', '["obliques","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखते हुए एक ऊंची तख़्त स्थिति में शुरुआत करें।","स्थिर स्थिति बनाए रखने के लिए अपने कोर और ग्लूट्स को संलग्न करें।","अपने धड़ को दाहिनी ओर घुमाएं, अपना दाहिना हाथ उठाएं और इसे छत की ओर बढ़ाएं।","मुड़ते समय अपने कूल्हों और पैरों को स्थिर रखें।","एक क्षण रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","बाईं ओर मोड़ को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3315', 'Full Maltese', 'waist', 'abs', '["shoulders","chest"]', 'body weight', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपनी बाहों को बगल की ओर सीधा फैलाकर खड़े होकर शुरुआत करें।","अपनी भुजाओं को सीधा रखते हुए धीरे-धीरे आगे की ओर झुकें, जब तक कि आपका ऊपरी शरीर ज़मीन के समानांतर न हो जाए।","अपने कोर को संलग्न करें और कुछ सेकंड के लिए इस स्थिति में रहें।","अपने पैरों से धक्का देकर और वापस खड़े होकर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3299', 'Full Planche', 'waist', 'abs', '["shoulders","chest","triceps"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई पर अलग रखते हुए और अपनी उंगलियों को आगे की ओर रखते हुए पुश-अप स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने पैरों को जमीन से ऊपर उठाते हुए धीरे-धीरे अपना वजन आगे बढ़ाएं।","अपने वजन को तब तक आगे बढ़ाना जारी रखें जब तक कि आपका शरीर आपके हाथों पर संतुलन बनाते हुए जमीन के समानांतर न हो जाए।","शरीर की सीधी रेखा बनाए रखते हुए इस स्थिति में जितनी देर तक हो सके रुकें।","धीरे-धीरे अपने पैरों को वापस जमीन पर लाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3327', 'Full Planche Push-Up', 'chest', 'pectorals', '["shoulders","triceps","core"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक फैलाकर पुश-अप स्थिति में शुरू करें।","अपने कोर को संलग्न करें और अपने शरीर को जमीन की ओर नीचे करें, अपनी कोहनियों को अपने किनारों के करीब रखें।","जैसे ही आप खुद को नीचे करते हैं, अपने शरीर को आगे की ओर झुकाएं और अपने हाथों पर संतुलन बनाते हुए अपने पैरों को जमीन से ऊपर उठाएं।","अपने शरीर को तब तक नीचे करना जारी रखें जब तक कि आपकी छाती ज़मीन से ठीक ऊपर न आ जाए।","अपने हाथों से धक्का दें और अपने शरीर को वापस प्रारंभिक स्थिति में उठाने के लिए अपनी भुजाओं को फैलाएँ।","पूरे आंदोलन के दौरान अपने सिर से एड़ी तक एक सीधी रेखा बनाए रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0466', 'Gironda Sternum Chin', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'body weight', 'strength', NULL, '["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए एक ऊंची पट्टी की ओर मुंह करके खड़े हो जाएं।","ऊपर पहुंचें और कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ बार को पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके बार से लटकें।","अपनी छाती को बार की ओर खींचने के लिए अपने लैट्स और बाइसेप्स को संलग्न करें, जो आपके उरोस्थि के साथ आगे बढ़े।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3561', 'Glute Bridge March', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने ग्लूट्स को संलग्न करें और अपने कूल्हों को ज़मीन से ऊपर उठाएं, जिससे आपके घुटनों से लेकर आपके कंधों तक एक सीधी रेखा बन जाए।","अपने कूल्हों को ऊपर उठाते हुए, एक पैर को ज़मीन से ऊपर उठाएं और अपने घुटने को अपनी छाती की ओर लाएँ।","अपने पैर को वापस ज़मीन पर टिकाएँ और दूसरे पैर से भी यही क्रिया दोहराएँ।","पुल की स्थिति को बनाए रखते हुए मार्चिंग गति में पैरों को बारी-बारी से जारी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3523', 'Glute Bridge Two Legs On Bench (Male)', 'upper legs', 'glutes', '["hamstrings","core"]', 'body weight', 'strength', NULL, '["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच के किनारे पर अपनी पीठ टिकाकर बैठें और आपके पैर ज़मीन पर सपाट हों।","समर्थन के लिए अपने हाथों को अपने कूल्हों के पास बेंच पर रखें।","अपने ग्लूट्स और हैमस्ट्रिंग को संलग्न करें, फिर अपने कूल्हों को बेंच से तब तक उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3193', 'Glute-Ham Raise', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'body weight', 'strength', NULL, '["Adjust the glute-ham raise machine to fit your body.","Position yourself face down on the machine with your ankles secured.","Place your hands on your chest or cross them over your chest.","Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Continue lifting until your body is in a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने शरीर में फिट होने के लिए ग्लूट-हैम रेज़ मशीन को समायोजित करें।","अपनी एड़ियों को सुरक्षित रखते हुए अपने आप को मशीन पर नीचे की ओर रखें।","अपने हाथों को अपनी छाती पर रखें या उन्हें अपनी छाती के ऊपर से क्रॉस करें।","अपने ऊपरी शरीर को छत की ओर ऊपर उठाने के लिए अपनी हैमस्ट्रिंग और ग्लूट्स को शामिल करें।","तब तक उठाना जारी रखें जब तक आपका शरीर आपके सिर से आपकी एड़ी तक एक सीधी रेखा में न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0467', 'Gorilla Chin', 'waist', 'abs', '["forearms","biceps"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","पुल-अप बार को कंधे की चौड़ाई से थोड़ा चौड़ा ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर रखते हुए बार से लटकें।","अपने कोर को संलग्न करें और अपने शरीर को बार की ओर खींचें, अपनी ठुड्डी को बार के ऊपर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0469', 'Groin Crunch', 'waist', 'abs', '["hip flexors","inner thighs"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को संलग्न करते हुए, अपने पैरों को जमीन से ऊपर उठाएं, अपने घुटनों को अपनी छाती की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1383', 'Hack Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to a comfortable weight.","Stand on the sled machine with your toes on the platform and your heels hanging off.","Hold onto the handles for stability.","Raise your heels as high as possible by pushing through the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्लेज मशीन को आरामदायक वजन के अनुसार समायोजित करें।","स्लेज मशीन पर अपने पैर की उंगलियों को प्लेटफॉर्म पर रखें और अपनी एड़ियों को लटकाकर खड़े रहें।","स्थिरता के लिए हैंडल को पकड़ें।","अपने पैरों की उंगलियों से धक्का देकर अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1384', 'Hack One Leg Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'sled machine', 'strength', NULL, '["Adjust the sled machine to an appropriate weight.","Stand on the sled machine with one foot, keeping the other foot off the ground.","Hold onto the handles for stability.","Raise your heel as high as possible, lifting your body up on the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions.","Switch legs and repeat the exercise."]', '["स्लेज मशीन को उचित वजन पर समायोजित करें।","स्लेज मशीन पर एक पैर से खड़े रहें, दूसरे पैर को जमीन से ऊपर रखें।","स्थिरता के लिए हैंडल को पकड़ें।","अपनी एड़ी को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर को अपने पैर की गेंद पर ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।","पैर बदलें और व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3221', 'Half Knee Bends (Male)', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को नीचे झुकाएँ जैसे कि आप कुर्सी पर पीछे बैठे हों।","अपनी छाती ऊपर रखें और अपना वजन अपनी एड़ियों पर रखें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-3202', 'Half Sit-Up (Male)', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1511', 'Hamstring Stretch', 'upper legs', 'hamstrings', '["glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Step forward with your right foot and shift your weight onto your right leg.","Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने दाहिने पैर के साथ आगे बढ़ें और अपना वजन अपने दाहिने पैर पर डालें।","अपनी पीठ को सीधा रखते हुए, धीरे-धीरे कूल्हों पर आगे की ओर झुकें, दोनों हाथों से अपने दाहिने पैर की ओर पहुँचें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2139', 'Hands Bike', 'chest', 'pectorals', '["triceps","shoulders"]', 'upper body ergometer', 'strength', NULL, '["Adjust the seat height and handlebar position to a comfortable level.","Sit on the ergometer with your back straight and feet on the pedals.","Grasp the handles with your hands and position your arms at a 90-degree angle.","Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Continue pedaling for the desired duration or number of repetitions."]', '["सीट की ऊंचाई और हैंडलबार की स्थिति को आरामदायक स्तर पर समायोजित करें।","एर्गोमीटर पर अपनी पीठ सीधी और पैर पैडल पर रखकर बैठें।","अपने हाथों से हैंडल को पकड़ें और अपनी भुजाओं को 90 डिग्री के कोण पर रखें।","अपने हाथों से पैडल चलाना शुरू करें, नियंत्रित गति में हैंडल को धक्का दें और खींचें।","वांछित अवधि या दोहराव की संख्या तक पैडल चलाना जारी रखें।"]', NULL, 7.5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-3218', 'Hands Clasped Circular Toe Touch (Male)', 'upper legs', 'glutes', '["hamstrings","quadriceps","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके हाथ आपकी छाती के सामने एक साथ जुड़े हुए हों।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपने हाथों को अपने पैर की उंगलियों की ओर गोलाकार गति में लाएं, बिना तनाव के जितना संभव हो उतना दूर तक पहुंचें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3215', 'Hands Reversed Clasped Circular Toe Touch (Male)', 'upper legs', 'glutes', '["hamstrings","quadriceps","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी भुजाएं बगल तक फैला लें।","अपनी पीठ सीधी और घुटने थोड़े मुड़े हुए रखते हुए कमर के बल आगे की ओर झुकें।","अपने हाथों को नीचे पहुंचाएं और उन्हें अपने पैरों के पीछे एक साथ पकड़ लें।","अपने पैरों को सीधा रखते हुए धीरे-धीरे अपने हाथों को गोलाकार गति में ऊपर और अपने सिर के ऊपर उठाएं।","जब तक आपके हाथ आपके पैर की उंगलियों को न छू लें तब तक गोलाकार गति जारी रखें।","गति को उल्टा करें और अपने हाथों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3302', 'Handstand', 'upper arms', 'triceps', '["shoulders","core"]', 'body weight', 'strength', NULL, '["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."]', '["हाथ के बल खड़े होने के लिए पर्याप्त जगह वाली खुली जगह ढूंढें।","अपने हाथों को कंधे की चौड़ाई पर जमीन पर रखें, उंगलियां आगे की ओर हों।","संतुलन बनाए रखने के लिए अपने कोर और कंधों का उपयोग करते हुए, अपने पैरों को दीवार की ओर उठाएं।","एक बार हाथ के बल खड़े होने की स्थिति में, अपने शरीर के वजन को सहारा देने के लिए अपने ट्राइसेप्स को संलग्न करें।","जब तक आप संतुलन बनाए रख सकते हैं तब तक हैंडस्टैंड को पकड़कर रखें।","नीचे आने के लिए धीरे-धीरे अपने पैरों को वापस ज़मीन पर टिकाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0471', 'Handstand Push-Up', 'upper arms', 'triceps', '["shoulders","chest","core"]', 'body weight', 'strength', 'expert', '["Find a wall and face away from it, standing a few feet away.","Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]', '["एक दीवार ढूंढें और उससे दूर मुख करके, कुछ फीट की दूरी पर खड़े हो जाएं।","अपने हाथों को कंधे की चौड़ाई पर जमीन पर रखें और हाथ के बल खड़े होने की स्थिति में आकर अपने पैरों को दीवार से सटाएं।","अपनी कोहनियों को मोड़ें और अपने शरीर को सीधी रेखा में रखते हुए अपने सिर को ज़मीन की ओर नीचे करें।","प्रारंभिक स्थिति में लौटने के लिए अपने हाथों से धक्का दें और अपनी भुजाओं को फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Handstand_Push-Ups/0.jpg","Handstand_Push-Ups/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1764', 'Hanging Leg Hip Raise', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने कूल्हों और घुटनों को मोड़कर अपने पैरों को ऊपर उठाएं जब तक कि आपकी जांघें जमीन के समानांतर न हों।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0472', 'Hanging Leg Raise', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'expert', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं, उन्हें सीधा रखें।","तब तक उठाना जारी रखें जब तक कि आपके पैर जमीन के समानांतर या उतने ऊपर न आ जाएं जितना आप आराम से जा सकें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Hanging_Leg_Raise/0.jpg","Hanging_Leg_Raise/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-1761', 'Hanging Oblique Knee Raise', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने घुटनों को अपनी छाती की ओर उठाएं, ऐसा करते समय अपने धड़ को बगल की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","अपने धड़ को विपरीत दिशा में घुमाते हुए दूसरी तरफ भी दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0473', 'Hanging Pike', 'waist', 'abs', '["hip flexors","shoulders"]', 'body weight', 'strength', 'expert', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up towards the bar, keeping them straight.","Continue lifting until your body forms a ''V'' shape, with your legs parallel to the ground.","Hold the position for a moment, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को सीधा रखते हुए बार की ओर ऊपर उठाएं।","तब तक उठाना जारी रखें जब तक कि आपका शरीर ''वी'' आकार न बना ले, जिसमें आपके पैर जमीन के समानांतर हों।","एक क्षण के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Hanging_Pike/0.jpg","Hanging_Pike/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0474', 'Hanging Straight Leg Hip Raise', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0475', 'Hanging Straight Leg Raise', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं, उन्हें सीधा रखें।","तब तक उठाना जारी रखें जब तक कि आपके पैर जमीन के समानांतर या उतने ऊपर न आ जाएं जितना आप आराम से जा सकें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0476', 'Hanging Straight Twisting Leg Hip Raise', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को सीधा करके पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को सीधा रखते हुए अपनी छाती की ओर ऊपर उठाएं।","एक बार जब आपके पैर जमीन के समानांतर हों, तो अपने कूल्हों को एक तरफ मोड़ें, अपने पैरों को उस तरफ लाएं।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","इस क्रिया को दोहराएं, लेकिन इस बार अपने कूल्हों को विपरीत दिशा में मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3636', 'High Knee Against Wall', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes","calves"]', 'body weight', 'cardio', NULL, '["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."]', '["अपने पैरों को कूल्हे की चौड़ाई की दूरी पर रखते हुए दीवार की ओर मुंह करके खड़े हो जाएं।","सहारे के लिए अपने हाथों को दीवार पर रखें।","अपने कोर को संलग्न करें और अपने दाहिने घुटने को अपनी छाती की ओर ऊपर उठाएं, जबकि अपने बाएं पैर को जमीन पर रखें।","तेजी से पैर बदलें, अपने बाएं घुटने को अपनी छाती की ओर लाएं और अपने दाहिने पैर को वापस नीचे लाएं।","अपने घुटनों को जितना संभव हो उतना ऊपर लाते हुए, पैरों को दौड़ने की गति में बदलना जारी रखें।","तेज़ गति बनाए रखें और पूरे अभ्यास के दौरान अपने ऊपरी शरीर को स्थिर रखें।","वांछित अवधि या दोहराव की संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-0484', 'Hip Raise (Bent Knee)', 'waist', 'abs', '["glutes","hamstrings"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को बगल में रखें, हथेलियाँ नीचे की ओर हों।","अपने कोर और ग्लूट्स को शामिल करें, फिर अपने कूल्हों को ज़मीन से ऊपर उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Bent-Knee_Hip_Raise/0.jpg","Bent-Knee_Hip_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1418', 'Hug Keens To Chest', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'body weight', 'strength', NULL, '["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर शुरुआत करें।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","जैसे ही आप बैठते हैं, अपने घुटनों को अपनी छाती की ओर लाएँ और उन्हें अपनी बाहों से पकड़ें।","एक क्षण के लिए इस स्थिति में रहें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3234', 'Hyght Dumbbell Fly', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, एक बेंच पर सीधे लेट जाएँ।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी कोहनियों को थोड़ा सा मोड़ते हुए, डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें जब तक कि आप अपनी छाती में खिंचाव महसूस न करें।","एक पल के लिए रुकें, फिर गति को उल्टा करें और डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0489', 'Hyperextension', 'back', 'spine', '["glutes","hamstrings"]', 'body weight', 'strength', NULL, '["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]', '["हाइपरएक्स्टेंशन बेंच को समायोजित करें ताकि आपकी ऊपरी जांघें पैड पर टिकी रहें और आपके पैर सुरक्षित रहें।","अपनी बाहों को अपनी छाती के ऊपर से पार करें या अपने हाथों को अपने सिर के पीछे रखें।","अपनी पीठ को सीधा रखते हुए अपने ऊपरी शरीर को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपने ऊपरी शरीर को वापस ऊपर उठाएं जब तक कि यह आपके पैरों के अनुरूप न हो जाए।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0488', 'Hyperextension (On Bench)', 'back', 'spine', '["glutes","hamstrings"]', 'body weight', 'strength', NULL, '["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]', '["हाइपरएक्स्टेंशन बेंच को समायोजित करें ताकि आपके कूल्हे पैड पर आराम से आराम कर रहे हों और आपके पैर सुरक्षित हों।","अपनी बाहों को अपनी छाती के ऊपर से पार करें या अपने हाथों को अपने सिर के पीछे रखें।","अपनी पीठ को सीधा रखते हुए धीरे-धीरे अपने ऊपरी शरीर को जमीन की ओर नीचे लाएं।","नीचे एक पल के लिए रुकें, फिर अपने ऊपरी शरीर को वापस ऊपर उठाएं जब तक कि यह आपके पैरों के अनुरूप न हो जाए।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3289', 'Impossible Dips', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी भुजाओं को पूरी तरह फैलाकर और अपने शरीर को हवा में लटकाकर अपने आप को दो समानांतर पट्टियों के बीच रखें।","अपने घुटनों को मोड़ें और अपनी एड़ियों को क्रॉस करें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ ज़मीन के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1471', 'Inchworm', 'waist', 'abs', '["shoulders","hamstrings"]', 'body weight', 'strength', 'beginner', '["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Once your hands reach your feet, stand back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कूल्हे की चौड़ाई से अलग रखते हुए खड़े होकर शुरुआत करें।","कमर के बल आगे की ओर झुकें और अपने हाथों को अपने सामने ज़मीन पर रखें।","अपने हाथों को तब तक आगे की ओर ले जाएं जब तक कि आप ऊंचे तख़्ते की स्थिति में न आ जाएं, अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखें।","एक पल के लिए रुकें, फिर अपने हाथों को अपने पैरों की ओर वापस ले जाएं, अपने पैरों को जितना संभव हो उतना सीधा रखें।","एक बार जब आपके हाथ आपके पैरों तक पहुंच जाएं, तो वापस प्रारंभिक स्थिति में खड़े हो जाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Inchworm/0.jpg","Inchworm/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3698', 'Inchworm v. 2', 'waist', 'abs', '["shoulders","hamstrings"]', 'body weight', 'strength', NULL, '["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."]', '["अपने पैरों को कूल्हे की चौड़ाई से अलग रखते हुए खड़े होकर शुरुआत करें।","कमर के बल आगे की ओर झुकें और अपने हाथों को अपने सामने ज़मीन पर रखें।","अपने हाथों को तब तक आगे की ओर ले जाएं जब तक कि आप ऊंचे तख़्ते की स्थिति में न आ जाएं, अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखें।","अपने पैरों को सीधा रखते हुए, अपने पैरों को अपने हाथों की ओर ले जाएं, अपने कूल्हों को छत की ओर लाएं।","वांछित संख्या में दोहराव के लिए इस क्रिया को दोहराते हुए, अपने हाथों को आगे की ओर चलाना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0490', 'Incline Close-Grip Push-Up', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', 'beginner', '["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को किसी ऊंची सतह, जैसे बेंच या सीढ़ी, पर कंधे की चौड़ाई से थोड़ी अधिक दूरी पर रखें।","अपने पैरों को अपने पीछे फैलाएं, अपने पैरों की उंगलियों पर आराम करते हुए, अपने शरीर को सिर से एड़ी तक एक सीधी रेखा बनाते हुए।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपनी छाती को ऊँची सतह की ओर नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Incline_Push-Up_Close-Grip/0.jpg","Incline_Push-Up_Close-Grip/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0491', 'Incline Leg Hip Raise (Leg Straight)', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच पर लेटें और अपनी पीठ को बेंच से सटाकर रखें और आपके पैर आपके सामने सीधे फैले हुए हों।","समर्थन के लिए अपने हाथों को बेंच के किनारों पर रखें।","अपने एब्स को शामिल करते हुए, अपने पैरों को बेंच से ऊपर उठाएं, उन्हें सीधा रखते हुए जितना हो सके उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0492', 'Incline Push Up Depth Jump', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', NULL, '["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step your feet back, keeping your body in a straight line from head to heels.","Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Push through your palms to extend your arms and return to the starting position.","Jump off the edge of the surface, landing softly with your knees slightly bent.","Repeat the push-up and depth jump for the desired number of repetitions."]', '["एक ऊंची सतह, जैसे कि बेंच या सीढ़ी ढूंढें, और अपने हाथों को किनारे पर कंधे की चौड़ाई से अलग रखें।","अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखते हुए अपने पैरों को पीछे ले जाएं।","अपनी कोहनियों को मोड़ते हुए और अपने शरीर को संरेखित रखते हुए, अपनी छाती को सतह के किनारे की ओर नीचे करें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","सतह के किनारे से कूदें, अपने घुटनों को थोड़ा मोड़कर धीरे से उतरें।","दोहराव की वांछित संख्या के लिए पुश-अप और डेप्थ जंप को दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0493', 'Incline Push-Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', 'beginner', '["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को किसी ऊंची सतह, जैसे बेंच या सीढ़ी, पर कंधे की चौड़ाई से थोड़ी अधिक दूरी पर रखें।","अपने पैरों को अपने पीछे फैलाएं, अपने पैरों की उंगलियों पर आराम करते हुए, अपने सिर से अपनी एड़ी तक एक सीधी रेखा बनाएं।","अपने शरीर को सीधी रेखा में रखते हुए, अपनी कोहनियों को मोड़कर अपनी छाती को ऊँची सतह की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Incline_Push-Up/0.jpg","Incline_Push-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3785', 'Incline Push-Up (On Box)', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को किसी बक्से या ऊँची सतह के किनारे पर रखें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","अपने पैरों को अपने पीछे फैलाएं, अपने पैरों की उंगलियों पर आराम करते हुए, अपने सिर से अपनी एड़ी तक एक सीधी रेखा बनाएं।","अपने शरीर को सीधी रेखा में रखते हुए, अपनी कोहनियों को मोड़कर अपनी छाती को बॉक्स की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0494', 'Incline Reverse Grip Push-Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', 'beginner', '["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को किसी बेंच के किनारे या ऊँची सतह पर रखें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","अपने पैरों को अपने पीछे फैलाएं, अपने पैरों की उंगलियों पर आराम करते हुए, अपने सिर से अपनी एड़ी तक एक सीधी रेखा बनाएं।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपनी छाती को बेंच की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को फैलाकर खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Incline_Push-Up_Reverse_Grip/0.jpg","Incline_Push-Up_Reverse_Grip/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3011', 'Incline Scapula Push Up', 'chest', 'serratus anterior', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक दूरी पर बेंच पर रखें।","अपने पैरों को कूल्हे की चौड़ाई के बराबर दूरी पर ज़मीन पर रखें।","अपनी कोहनियों को अंदर की ओर रखते हुए अपनी छाती को बेंच की ओर नीचे करें।","जैसे ही आप नीचे आते हैं, अपने स्कैपुला को एक साथ निचोड़ते हुए, अपने कंधे के ब्लेड को पीछे हटा लें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0495', 'Incline Twisting Sit-Up', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने पैरों को फुट पैड के नीचे सुरक्षित रखते हुए बेंच पर लेट जाएँ।","अपने हाथों को अपने सिर के पीछे या अपनी छाती के पार रखें।","अपने पेट को संलग्न करें और अपने ऊपरी शरीर को बेंच से ऊपर उठाएं, आगे की ओर झुकें।","जैसे ही आप मुड़ते हैं, अपने धड़ को एक तरफ मोड़ें, अपनी कोहनी को विपरीत घुटने की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","इस बार अपने धड़ को दूसरी तरफ घुमाते हुए इस क्रिया को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1564', 'Intermediate Hip Flexor And Quad Stretch', 'upper legs', 'quads', '["hamstrings","glutes"]', 'rope', 'strength', NULL, '["Stand upright with your feet shoulder-width apart.","Hold onto a stable object for support.","Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.","Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the left side."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं।","समर्थन के लिए किसी स्थिर वस्तु को पकड़ें।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने पैर को अपने ग्लूट्स की ओर लाएँ, अपने दाहिने हाथ से रस्सी को पकड़ें।","धीरे-धीरे अपने दाहिने पैर को अपने ग्लूट्स की ओर खींचें, अपने दाहिने क्वाड में खिंचाव महसूस करें।","20-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और बाईं ओर दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0496', 'Inverse Leg Curl (Bench Support)', 'upper legs', 'hamstrings', '["glutes","calves"]', 'body weight', 'strength', NULL, '["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने कूल्हों को किनारे पर रखकर एक बेंच पर मुंह करके लेट जाएं और आपके पैर आपके पीछे सीधे फैले हुए हों।","समर्थन के लिए बेंच को पकड़ें।","अपने ऊपरी शरीर को स्थिर रखते हुए, अपने घुटनों को मोड़ें और अपने पैरों को अपने ग्लूट्स की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2400', 'Inverse Leg Curl (On Pull-Up Cable Machine)', 'upper legs', 'hamstrings', '["glutes","calves"]', 'body weight', 'strength', NULL, '["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को समायोजित करें ताकि टखने की पट्टियाँ सबसे कम सेटिंग पर हों।","अपने पैरों को फैलाकर और टखने की पट्टियों को अपने पैरों से जोड़कर बेंच पर मुंह के बल लेट जाएं।","स्थिरता के लिए बेंच के हैंडल को पकड़ें।","अपने घुटनों को मोड़ें और अपने पैरों को अपने ग्लूट्स की ओर मोड़ें, जिससे आपकी हैमस्ट्रिंग दब जाए।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0499', 'Inverted Row', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Set up a bar at waist height or use a suspension trainer.","Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]', '["कमर की ऊंचाई पर बार स्थापित करें या सस्पेंशन ट्रेनर का उपयोग करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बार या सस्पेंशन ट्रेनर की ओर मुंह करके खड़े हो जाएं।","बार या हैंडल को कंधे की चौड़ाई से थोड़ा चौड़ा ओवरहैंड पकड़ से पकड़ें।","अपने शरीर को सीधा और अपनी एड़ियों को ज़मीन पर रखते हुए पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए अपनी छाती को बार या हैंडल की ओर खींचें।","शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे अपने आप को प्रारंभिक स्थिति में वापस ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2300', 'Inverted Row Bent Knees', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["कमर की ऊंचाई पर एक बार स्थापित करें और उसके नीचे लेट जाएं।","बार को ओवरहैंड ग्रिप से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","अपने शरीर को इस प्रकार रखें कि आपकी एड़ियाँ ज़मीन पर हों और आपका शरीर सीधा हो।","अपने कंधे के ब्लेड को एक साथ दबाकर अपनी छाती को बार की ओर ऊपर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2298', 'Inverted Row On Bench', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["ऐसी ऊंचाई पर एक बेंच स्थापित करें जिससे आपका शरीर उसके नीचे स्वतंत्र रूप से लटक सके।","बेंच की ओर सिर करके जमीन पर मुंह करके लेट जाएं।","ऊपर पहुंचें और कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ बेंच को पकड़ें।","अपने शरीर को इस प्रकार रखें कि आपकी एड़ियाँ ज़मीन पर हों और आपकी बाहें पूरी तरह फैली हुई हों।","जैसे ही आप अपनी छाती को बेंच की ओर ऊपर खींचते हैं, अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0497', 'Inverted Row v. 2', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्मिथ मशीन पर कमर की ऊंचाई पर बार स्थापित करें या सस्पेंशन ट्रेनर का उपयोग करें।","बार या सस्पेंशन ट्रेनर की ओर मुंह करके खड़े हो जाएं और हाथों को कंधे की चौड़ाई से अलग रखते हुए इसे ओवरहैंड ग्रिप से पकड़ें।","अपने पैरों को आगे की ओर झुकाते हुए आगे बढ़ें, जब तक कि आपका शरीर थोड़ा सा कोण पर न आ जाए।","अपने शरीर को सीधा रखें और अपनी छाती को बार या हैंडल की ओर ऊपर खींचें, अपने कंधे के ब्लेड को एक साथ दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0498', 'Inverted Row With Straps', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Set up a suspension trainer or straps at chest height.","Stand facing the anchor point and grab the handles with an overhand grip.","Walk your feet forward, leaning back until your body is at an angle.","Keep your body straight and engage your core.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]', '["छाती की ऊंचाई पर सस्पेंशन ट्रेनर या पट्टियाँ स्थापित करें।","एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं और हैंडल को ओवरहैंड ग्रिप से पकड़ लें।","अपने पैरों को आगे की ओर झुकाते हुए आगे बढ़ें, जब तक कि आपका शरीर एक कोण पर न आ जाए।","अपने शरीर को सीधा रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, अपनी छाती को हैंडल की ओर खींचें।","शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे अपने आप को प्रारंभिक स्थिति में वापस ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1419', 'Iron Cross Stretch', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपनी पीठ के बल लेट जाएँ और अपनी भुजाएँ बगल की ओर फैलाएँ।","अपने पैरों को सीधा रखते हुए छत की ओर ऊपर उठाएं।","धीरे-धीरे अपने पैरों को एक तरफ नीचे करें, अपने पैरों से फर्श को छूने का लक्ष्य रखें।","कुछ सेकंड के लिए खिंचाव को रोककर रखें, फिर अपने पैरों को शुरुआती स्थिति में लौटा दें।","दूसरी तरफ खिंचाव को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1297', 'Isometric Chest Squeeze', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपनी भुजाओं को अपने सामने सीधा फैलाएँ, ज़मीन के समानांतर, अपनी हथेलियाँ एक-दूसरे के सामने रखें।","अपनी बाहों को सीधा रखते हुए अपनी छाती की मांसपेशियों को जितना हो सके उतना जोर से दबाएं।","अपनी छाती की मांसपेशियों को सिकोड़ने पर ध्यान केंद्रित करते हुए कुछ सेकंड के लिए इस स्थिति में रहें।","दबाव छोड़ें और अपनी छाती की मांसपेशियों को आराम दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Isometric_Chest_Squeezes/0.jpg","Isometric_Chest_Squeezes/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0500', 'Isometric Wipers', 'chest', 'pectorals', '["shoulders","triceps","core"]', 'body weight', 'strength', 'beginner', '["Start by lying flat on your back on a mat or bench.","Extend your arms straight out to the sides, perpendicular to your body.","Engage your core and lift both legs off the ground, keeping them together and straight.","Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.","Pause for a moment, then use your core to lift your legs back to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["किसी चटाई या बेंच पर अपनी पीठ के बल सीधे लेटकर शुरुआत करें।","अपनी भुजाओं को अपने शरीर के लंबवत, बगल की ओर सीधा फैलाएँ।","अपने कोर को संलग्न करें और दोनों पैरों को एक साथ और सीधा रखते हुए जमीन से ऊपर उठाएं।","धीरे-धीरे अपने पैरों को एक तरफ नीचे करें, नियंत्रण बनाए रखते हुए अपने पैरों से जमीन को छूने का लक्ष्य रखें।","एक पल के लिए रुकें, फिर अपने पैरों को प्रारंभिक स्थिति में वापस उठाने के लिए अपने कोर का उपयोग करें।","इस क्रिया को दोहराएँ, इस बार अपने पैरों को विपरीत दिशा में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Isometric_Wipers/0.jpg","Isometric_Wipers/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0501', 'Jack Burpee', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves","shoulders","triceps","core"]', 'body weight', 'cardio', NULL, '["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए खड़े होकर शुरुआत करें।","अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ, अपने हाथों को अपने सामने ज़मीन पर रखें।","पुश-अप स्थिति में उतरते हुए अपने पैरों को पीछे किक करें।","एक पुश-अप करें, अपनी छाती को ज़मीन पर झुकाएँ और फिर वापस ऊपर की ओर धकेलें।","स्क्वाट स्थिति में उतरते हुए, अपने पैरों को आगे की ओर उछालें।","अपनी भुजाओं को ऊपर की ओर पहुँचाते हुए, विस्फोटक तरीके से ऊपर उठें।","अगली पुनरावृत्ति शुरू करने के लिए धीरे से उतरें और तुरंत वापस स्क्वाट स्थिति में आ जाएँ।"]', NULL, 8, 'time', 0, 'opengym', 1),
('og-3224', 'Jack Jump (Male)', 'cardio', 'cardiovascular system', '["quadriceps","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को एक साथ और अपनी भुजाओं को बगल में रखकर खड़े हो जाएं।","अपने पैरों को फैलाकर और अपनी बाहों को अपने सिर के ऊपर उठाकर ऊपर कूदें।","जैसे ही आप उतरें, तुरंत प्रारंभिक स्थिति में वापस आ जाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-0507', 'Jackknife Sit-Up', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your legs extended and your arms overhead.","Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी बाहों को ऊपर की ओर रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने कोर को संलग्न करें और अपने पैरों और ऊपरी शरीर को एक साथ उठाएं, अपने हाथों को अपने पैर की उंगलियों तक पहुंचाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों और शरीर के ऊपरी हिस्से को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Jackknife_Sit-Up/0.jpg","Jackknife_Sit-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0508', 'Janda Sit-Up', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Janda_Sit-Up/0.jpg","Janda_Sit-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2612', 'Jump Rope', 'cardio', 'cardiovascular system', '["calves","quadriceps","hamstrings","glutes"]', 'rope', 'cardio', NULL, '["Hold the handles of the jump rope with your hands, palms facing inward.","Stand with your feet shoulder-width apart and knees slightly bent.","Swing the rope over your head and jump over it as it comes towards your feet.","Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Continue jumping for the desired duration or number of repetitions."]', '["कूदने वाली रस्सी के हैंडल को अपने हाथों से पकड़ें, हथेलियाँ अंदर की ओर हों।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","रस्सी को अपने सिर के ऊपर घुमाएं और जैसे ही वह आपके पैरों की ओर आए तो उस पर कूदें।","अपने पैरों की उंगलियों पर धीरे से उतरें और जैसे ही रस्सी फिर से चारों ओर आ जाए, छलांग दोहराएँ।","वांछित अवधि या दोहराव की संख्या तक कूदना जारी रखें।"]', NULL, 11, 'time', 1, 'opengym', 1),
('og-0514', 'Jump Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively off the ground, extending your hips, knees, and ankles.","While in mid-air, quickly bring your arms forward for balance.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","अपने कूल्हों, घुटनों और टखनों को फैलाते हुए ज़मीन से तेज़ी से कूदें।","मध्य हवा में रहते हुए, संतुलन के लिए अपनी भुजाओं को शीघ्रता से आगे लाएँ।","अपने पैरों की उंगलियों पर धीरे से उतरें और तुरंत अगली पुनरावृत्ति पर जाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0513', 'Jump Squat v. 2', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","अपने कूल्हों और घुटनों को पूरी तरह फैलाते हुए विस्फोटक तरीके से कूदें।","अपने पैरों की उंगलियों पर धीरे से उतरें और तुरंत अपने शरीर को वापस स्क्वाट स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0517', 'Kettlebell Advanced Windmill', 'waist', 'abs', '["obliques","shoulders"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Keep your right arm extended overhead and your eyes on the kettlebell.","As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपने दाहिने हाथ में केटलबेल पकड़ें, अपना हाथ ऊपर की ओर फैलाएं और अपनी हथेली आगे की ओर रखें।","अपने बाएं पैर को थोड़ा दाहिनी ओर घुमाएं, और अपना वजन अपने बाएं पैर पर डालें।","अपने बाएं घुटने को मोड़ें और कूल्हे पर टिकाएं, अपने धड़ को बाईं ओर नीचे करें।","अपने दाहिने हाथ को ऊपर की ओर फैलाकर रखें और अपनी आँखें केटलबेल पर रखें।","जैसे ही आप अपना धड़ नीचे करते हैं, अपने दाहिने पैर को सीधा होने दें और अपने दाहिने पैर को थोड़ा घूमने दें।","अपने धड़ को तब तक नीचे करें जब तक आपको अपने बाएं हैमस्ट्रिंग में खिंचाव महसूस न हो और आपका दाहिना हाथ जमीन की ओर न हो जाए।","एक पल के लिए रुकें, फिर अपने कोर को संलग्न करें और प्रारंभिक स्थिति में लौटने के लिए अपनी बाईं एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', '["Advanced_Kettlebell_Windmill/0.jpg","Advanced_Kettlebell_Windmill/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0518', 'Kettlebell Alternating Hang Clean', 'lower arms', 'forearms', '["shoulders","traps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang in front of your body with your arms fully extended.","In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें।","अपनी बाहों को पूरी तरह फैलाकर केटलबेल्स को अपने शरीर के सामने लटकने दें।","एक तरल गति में, अपने कूल्हों को तेजी से फैलाएं, अपने कंधों को सिकोड़ें, और केटलबेल्स को अपने कंधों की ओर ऊपर खींचें।","जैसे ही केटलबेल कंधे की ऊँचाई तक पहुँचें, अपनी कलाइयों को घुमाएँ और केटलबेल को रैक स्थिति में पकड़ें, आपकी हथेलियाँ अंदर की ओर हों और केटलबेल आपके अग्रबाहु के बाहर की ओर टिकी हुई हों।","केटलबेल्स को वापस प्रारंभिक स्थिति में लाएँ और विपरीत भुजा से इस क्रिया को दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', '["Kettlebell_Hang_Clean/0.jpg","Kettlebell_Hang_Clean/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0520', 'Kettlebell Alternating Press', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead, fully extending your arm.","Lower the kettlebell back to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें।","अपनी बांह को पूरी तरह फैलाते हुए एक केटलबेल को ऊपर की ओर दबाएं।","केटलबेल को वापस कंधे की ऊँचाई तक नीचे लाएँ।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', '["Alternating_Kettlebell_Press/0.jpg","Alternating_Kettlebell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0519', 'Kettlebell Alternating Press On Floor', 'chest', 'pectorals', '["shoulders","triceps"]', 'kettlebell', 'strength', NULL, '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Continue alternating the press motion with each kettlebell for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए अपनी पीठ के बल फर्श पर लेटकर शुरुआत करें।","प्रत्येक हाथ में केटलबेल पकड़ें, आपकी हथेलियाँ आपके पैरों की ओर हों और आपकी भुजाएँ छत की ओर सीधी फैली हुई हों।","एक केटलबेल को अपने कंधे की ओर नीचे करें जबकि दूसरे केटलबेल को सीधा ऊपर की ओर फैलाकर रखें।","निचली केटलबेल को वापस प्रारंभिक स्थिति में दबाएं, साथ ही साथ दूसरी केटलबेल को अपने कंधे की ओर नीचे करें।","दोहराव की वांछित संख्या के लिए प्रत्येक केटलबेल के साथ प्रेस गति को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0521', 'Kettlebell Alternating Renegade Row', 'back', 'upper back', '["core","shoulders"]', 'kettlebell', 'strength', NULL, '["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने हाथों से केटलबेल्स को पकड़कर और अपने पैरों को कूल्हे-चौड़ाई से अलग करके एक उच्च तख़्त स्थिति में शुरुआत करें।","अपने कोर को व्यस्त रखें और अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखें।","अपनी कोहनी को अपने शरीर के पास रखते हुए, एक केटलबेल को अपनी छाती की ओर खींचें।","केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और दूसरे हाथ से दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0522', 'Kettlebell Alternating Row', 'back', 'upper back', '["biceps","forearms"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक केटलबेल पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें।","एक केटलबेल को अपनी छाती की ओर खींचें, अपनी कोहनी को अपने शरीर के करीब रखें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और दूसरे हाथ से दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', '["Alternating_Kettlebell_Row/0.jpg","Alternating_Kettlebell_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0523', 'Kettlebell Arnold Press', 'shoulders', 'delts', '["triceps","upper back"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें और अपनी हथेलियों को अपनी ओर रखें।","अपने कोर को संलग्न करें और केटलबेल्स को ऊपर की ओर दबाएं, अपनी हथेलियों को आगे की ओर घुमाते हुए अपनी बाहों को फैलाएं।","गति के शीर्ष पर रुकें, फिर धीरे-धीरे केटलबेल्स को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Kettlebell_Arnold_Press/0.jpg","Kettlebell_Arnold_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0524', 'Kettlebell Bent Press', 'waist', 'abs', '["shoulders","triceps","obliques"]', 'kettlebell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Rotate your torso to the left, shifting your weight onto your left foot.","Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","As you lower, keep your eyes on the kettlebell and your chest lifted.","Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में केटलबेल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी कोहनी को लॉक रखते हुए, अपने दाहिने हाथ से केटलबेल को ऊपर की ओर दबाएं।","अपने धड़ को बाईं ओर घुमाएं, अपना वजन अपने बाएं पैर पर डालें।","अपने बाएं घुटने को मोड़ें और अपने धड़ को ज़मीन की ओर नीचे करें, अपने दाहिने हाथ को ऊपर की ओर फैलाकर रखें।","जैसे ही आप नीचे उतरें, अपनी आँखें केटलबेल पर रखें और अपनी छाती ऊपर उठाएँ।","एक बार जब आपका बायाँ हाथ ज़मीन को छू ले, तो अपने बाएँ पैर से धक्का दें और अपने कूल्हों को आगे की ओर ले जाते हुए अपने बाएँ पैर को सीधा करें।","जैसे ही आप अपने कूल्हों को आगे बढ़ाते हैं, केटलबेल को शुरुआती स्थिति में वापस दबाने के लिए अपने मूल और दाहिने हाथ का उपयोग करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0525', 'Kettlebell Bottoms Up Clean From The Hang Position', 'upper arms', 'biceps', '["forearms","shoulders"]', 'kettlebell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebell to hang down between your legs, with your arm fully extended.","In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Lower the kettlebell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, एक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें।","अपनी बांह को पूरी तरह फैलाकर केटलबेल को अपने पैरों के बीच लटकने दें।","एक तरल गति में, केटलबेल को अपने कंधे की ओर खींचते हुए अपने कूल्हों और घुटनों को विस्फोटक रूप से फैलाएँ।","जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचे, अपनी कलाई को घुमाएं ताकि केटलबेल का निचला हिस्सा ऊपर की ओर रहे।","अपनी कोहनी मोड़कर और अपनी हथेली ऊपर की ओर करके केटलबेल को कंधे की ऊंचाई पर पकड़ें।","गति को उलट कर केटलबेल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0526', 'Kettlebell Double Alternating Hang Clean', 'upper arms', 'biceps', '["forearms","shoulders"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang straight down in front of your body.","In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें।","केटलबेल्स को अपने शरीर के सामने सीधा लटकने दें।","एक तरल गति में, अपने कंधों को सिकोड़ते हुए अपने कूल्हों और घुटनों को तेजी से फैलाएं।","जैसे ही केटलबेल्स ऊपर उठें, उन्हें अपने कंधों की ओर ऊपर खींचें, अपनी कोहनियों को ऊपर और बगल की ओर रखें।","केटलबेल्स को कंधे की ऊंचाई पर पकड़ें, आपकी हथेलियाँ अंदर की ओर हों और आपकी कोहनियाँ आगे की ओर हों।","केटलबेल्स को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', '["Double_Kettlebell_Alternating_Hang_Clean/0.jpg","Double_Kettlebell_Alternating_Hang_Clean/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0527', 'Kettlebell Double Jerk', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebells overhead, fully extending your arms.","Bend your knees and quickly drop into a partial squat.","Explosively extend your hips and knees, driving the kettlebells overhead.","Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Stand up straight and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल्स को ऊपर की ओर दबाएं।","अपने घुटनों को मोड़ें और जल्दी से आंशिक स्क्वाट में बैठ जाएं।","केटलबेल्स को सिर के ऊपर चलाते हुए अपने कूल्हों और घुटनों को तेजी से फैलाएं।","अपनी बाहों को लॉक करें और अपने घुटनों को थोड़ा मोड़कर केटलबेल्स को ऊपर की ओर पकड़ें।","सीधे खड़े हो जाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Double_Kettlebell_Jerk/0.jpg","Double_Kettlebell_Jerk/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0528', 'Kettlebell Double Push Press', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","As the kettlebells reach the top, press them fully overhead, locking out your arms.","Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर शुरुआत करें, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","अपने कूल्हों, घुटनों और टखनों को विस्फोटक रूप से फैलाकर, केटलबेल को ऊपर की ओर चलाकर आंदोलन शुरू करें।","जैसे ही केटलबेल शीर्ष पर पहुंचें, अपनी बाहों को लॉक करते हुए, उन्हें पूरी तरह से ऊपर की ओर दबाएं।","अपनी कोहनियों को मोड़कर और उन्हें वापस कंधे की ऊंचाई तक लाकर केटलबेल्स को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Double_Kettlebell_Push_Press/0.jpg","Double_Kettlebell_Push_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0529', 'Kettlebell Double Snatch', 'shoulders', 'delts', '["trapezius","forearms","core"]', 'kettlebell', 'strength', 'expert', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में अपनी जांघों के सामने एक हाथ की दूरी पर केटलबेल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ को सपाट और छाती को ऊपर रखें।","एक विस्फोटक गति में, अपने कूल्हों, घुटनों और टखनों को फैलाएँ, और साथ ही केटलबेल्स को अपने कंधों की ओर खींचें।","जैसे ही केटलबेल कंधे के स्तर पर पहुंचें, अपनी कलाइयों को घुमाएं और अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल को ऊपर की ओर मुक्का मारें।","केटलबेल्स को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', '["Double_Kettlebell_Snatch/0.jpg","Double_Kettlebell_Snatch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0530', 'Kettlebell Double Windmill', 'waist', 'abs', '["shoulders","hamstrings"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Extend your right arm overhead, keeping your eyes on the kettlebell.","Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Bend at the waist to the left, keeping your right arm extended overhead.","Lower the kettlebell towards the ground, reaching towards your left foot.","Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में केटलबेल पकड़ लें।","अपनी आँखें केटलबेल पर रखते हुए, अपना दाहिना हाथ ऊपर की ओर फैलाएँ।","अपने बाएँ पैर को बाईं ओर 45 डिग्री और अपने दाहिने पैर को दाईं ओर 90 डिग्री घुमाएँ।","अपने दाहिने हाथ को ऊपर की ओर फैलाए रखते हुए, कमर को बाईं ओर झुकाएँ।","अपने बाएँ पैर की ओर पहुँचते हुए केटलबेल को ज़मीन की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपने कोर को संलग्न करें और प्रारंभिक स्थिति में लौटने के लिए अपने दाहिने पैर से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', '["Double_Kettlebell_Windmill/0.jpg","Double_Kettlebell_Windmill/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0531', 'Kettlebell Extended Range One Arm Press On Floor', 'chest', 'pectorals', '["triceps","shoulders"]', 'kettlebell', 'strength', 'beginner', '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए अपनी पीठ के बल फर्श पर लेटकर शुरुआत करें।","एक हाथ में केटलबेल पकड़ें, आपकी हथेली आपके पैरों की ओर हो।","अपनी बांह को छत की ओर सीधा फैलाएं, अपनी कोहनी को लॉक रखें और अपनी कलाई को सीधा रखें।","पूरे आंदोलन के दौरान नियंत्रण बनाए रखते हुए, केटलबेल को धीरे-धीरे प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', '["Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg","Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0532', 'Kettlebell Figure 8', 'waist', 'abs', '["shoulders","forearms"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.","As the kettlebell comes forward, pass it to the other hand between your legs.","Continue passing the kettlebell between your legs in a figure 8 motion.","Maintain a steady pace and engage your core throughout the exercise.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में केटलबेल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","केटलबेल को अपने पैरों के बीच से गुजारें, जैसे ही यह आपके पैरों के पीछे तक पहुंचे, हाथ बदल लें।","जैसे ही केटलबेल आगे आए, उसे अपने पैरों के बीच दूसरे हाथ में दे दें।","अपने पैरों के बीच केटलबेल को आकृति 8 की गति में घुमाना जारी रखें।","एक स्थिर गति बनाए रखें और पूरे अभ्यास के दौरान अपने कोर को संलग्न रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Kettlebell_Figure_8/0.jpg","Kettlebell_Figure_8/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0533', 'Kettlebell Front Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'kettlebell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands in front of your chest, close to your body.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","केटलबेल को दोनों हाथों से अपनी छाती के सामने, अपने शरीर के करीब पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों को नीचे और पीछे करते समय अपनी छाती को ऊपर रखें, जैसे कि एक कुर्सी पर बैठे हों।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","वापस खड़े होने के लिए अपनी एड़ियों के माध्यम से ड्राइव करें, शीर्ष पर अपने ग्लूट्स को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0534', 'Kettlebell Goblet Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'kettlebell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से केटलबेल को अपनी छाती के पास पकड़ें।","अपनी छाती को ऊपर और मुख्य भाग को ऊपर रखते हुए, घुटनों और कूल्हों पर झुकते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0535', 'Kettlebell Hang Clean', 'upper legs', 'hamstrings', '["glutes","quadriceps","calves"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower the kettlebell towards the ground, allowing it to swing between your legs.","Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.","Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी जांघों के सामने केटलबेल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","केटलबेल को ज़मीन की ओर नीचे करें, जिससे यह आपके पैरों के बीच झूल सके।","केटलबेल को कंधे की ऊंचाई तक घुमाने के लिए गति का उपयोग करते हुए, जल्दी से अपने कूल्हों और घुटनों को फैलाएं।","जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपनी कलाइयों को घुमाएं और केटलबेल को रैक स्थिति में पकड़ें, अपनी कोहनी को अंदर की ओर रखें और केटलबेल को अपने अग्रबाहु पर टिकाएं।","केटलबेल को वापस अपने पैरों के बीच प्रारंभिक स्थिति में लाएँ, और वांछित संख्या में दोहराव के लिए दोहराएं।"]', '["Kettlebell_Hang_Clean/0.jpg","Kettlebell_Hang_Clean/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0536', 'Kettlebell Lunge Pass Through', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'kettlebell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से अपनी छाती के सामने केटलबेल पकड़ें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं।","जैसे ही आप आगे बढ़ते हैं, केटलबेल को अपनी दाहिनी जांघ के नीचे से गुजारें और इसे अपने बाएं हाथ में स्थानांतरित करें।","प्रारंभिक स्थिति में लौटने के लिए अपने दाहिने पैर से धक्का दें, साथ ही केटलबेल को अपने दाहिने हाथ पर वापस पास करें।","केटलबेल को अपनी बायीं जांघ के नीचे से गुजारते हुए, विपरीत दिशा में लंज को दोहराएं।","दोहराव की वांछित संख्या के लिए बारी-बारी से फेफड़े चलाना और केटलबेल को हाथों के बीच से गुजारना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0537', 'Kettlebell One Arm Clean And Jerk', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, एक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, अपने पैरों के बीच केटलबेल को नीचे करें।","केटलबेल को कंधे की ऊंचाई तक घुमाने के लिए गति का उपयोग करते हुए, अपने कूल्हों, घुटनों और टखनों को तेजी से फैलाएं।","जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपनी कलाई को घुमाएं और अपने हाथ को सीधा ऊपर की ओर मुक्का मारें, जिससे आपका हाथ ऊपर की ओर लॉक हो जाए।","केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', '["One-Arm_Kettlebell_Clean_and_Jerk/0.jpg","One-Arm_Kettlebell_Clean_and_Jerk/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1298', 'Kettlebell One Arm Floor Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'kettlebell', 'strength', 'intermediate', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए फर्श पर अपनी पीठ के बल लेट जाएं।","केटलबेल को एक हाथ में पकड़ें, अपनी हथेली को अपने पैरों की ओर रखें और आपका हाथ छत की ओर सीधा फैला हुआ हो।","अपनी कोहनी को मोड़कर, अपनी ऊपरी भुजा को अपने शरीर के पास रखते हुए केटलबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएँ।","जब केटलबेल आपकी छाती के ठीक ऊपर हो तो एक क्षण के लिए रुकें, फिर अपनी कोहनी बढ़ाकर इसे वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', '["One-Arm_Kettlebell_Floor_Press/0.jpg","One-Arm_Kettlebell_Floor_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0538', 'Kettlebell One Arm Jerk', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebell overhead in a straight line, fully extending your arm.","As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","अपनी बांह को पूरी तरह फैलाते हुए केटलबेल को एक सीधी रेखा में ऊपर की ओर दबाएं।","जैसे ही आप केटलबेल को ऊपर की ओर दबाते हैं, उसी समय अपने घुटनों को डुबोएं और गति उत्पन्न करने के लिए उन्हें जल्दी से सीधा करें।","जैसे ही केटलबेल अपने उच्चतम बिंदु पर पहुंचे, अपने घुटनों और कूल्हों को मोड़कर जल्दी से इसके नीचे आ जाएं।","अपने घुटनों और कूल्हों को थोड़ा मोड़कर और अपनी बांह को पूरी तरह ऊपर की ओर फैलाकर केटलबेल को पकड़ें।","अपने घुटनों और कूल्हों को पूरी तरह फैलाते हुए सीधे खड़े हो जाएं और केटलबेल को सिर के ऊपर स्थिर कर लें।","अपने घुटनों और कूल्हों को मोड़कर केटलबेल को शुरुआती स्थिति में वापस लाएं और वांछित संख्या में दोहराव के लिए दोहराएं।"]', '["One-Arm_Kettlebell_Jerk/0.jpg","One-Arm_Kettlebell_Jerk/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0539', 'Kettlebell One Arm Military Press To The Side', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Engage your core and keep your back straight.","Press the kettlebell overhead, extending your arm fully.","Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें।","अपने कोर को व्यस्त रखें और अपनी पीठ सीधी रखें।","अपनी बांह को पूरी तरह फैलाते हुए केटलबेल को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', '["One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg","One-Arm_Kettlebell_Military_Press_To_The_Side/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0540', 'Kettlebell One Arm Push Press', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Bend your knees slightly and engage your core.","Press the kettlebell overhead by extending your arm and fully extending your legs.","Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में कंधे के स्तर पर केटलबेल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","अपनी बांह को फैलाकर और अपने पैरों को पूरी तरह फैलाकर केटलबेल को ऊपर की ओर दबाएं।","अपने घुटनों को मोड़कर और केटलबेल को वापस अपने कंधे पर लाकर केटलबेल को शुरुआती स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', '["One-Arm_Kettlebell_Push_Press/0.jpg","One-Arm_Kettlebell_Push_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0541', 'Kettlebell One Arm Row', 'back', 'upper back', '["biceps","forearms"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, एक हाथ में केटलबेल को ओवरहैंड पकड़ के साथ पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","केटलबेल को अपनी छाती की ओर ऊपर खींचें, अपनी कोहनी को अपने शरीर के करीब रखें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें और दूसरे हाथ से दोहराएं।"]', '["One-Arm_Kettlebell_Row/0.jpg","One-Arm_Kettlebell_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0542', 'Kettlebell One Arm Snatch', 'shoulders', 'delts', '["trapezius","forearms","core"]', 'kettlebell', 'strength', 'expert', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपने पैरों के बीच एक हाथ में केटलबेल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, केटलबेल को ज़मीन की ओर नीचे करें।","केटलबेल को अपने कंधे की ओर ऊपर घुमाने के लिए गति का उपयोग करते हुए, अपने कूल्हों और घुटनों को तेजी से फैलाएँ।","जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपने हाथ को घुमाएं और अपनी बांह को पूरी तरह फैलाते हुए इसे सीधे ऊपर की ओर मुक्का मारें।","केटलबेल को वापस अपने पैरों के बीच नीचे लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', '["One-Arm_Kettlebell_Snatch/0.jpg","One-Arm_Kettlebell_Snatch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0543', 'Kettlebell Pirate Supper Legs', 'shoulders', 'delts', '["triceps","forearms"]', 'kettlebell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Extend your arm fully overhead, straightening your elbow.","Lower the kettlebell back down to shoulder height, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में केटलबेल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी कोहनी को अपने शरीर के करीब रखते हुए केटलबेल को कंधे की ऊंचाई तक उठाएं।","अपनी कोहनी को सीधा करते हुए अपने हाथ को पूरी तरह ऊपर की ओर फैलाएं।","केटलबेल को वापस कंधे की ऊँचाई तक नीचे लाएँ, फिर प्रारंभिक स्थिति में लौट आएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0544', 'Kettlebell Pistol Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'kettlebell', 'strength', 'expert', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.","Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से अपनी छाती के सामने केटलबेल पकड़ें।","अपने बाएँ पैर को ज़मीन से उठाएँ और ज़मीन के समानांतर रखते हुए आगे की ओर फैलाएँ।","धीरे-धीरे अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ, अपने दाहिने पैर को ज़मीन पर सपाट रखें और अपने बाएँ पैर को फैलाएँ।","स्क्वाट के निचले हिस्से में एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', '["Kettlebell_Pistol_Squat/0.jpg","Kettlebell_Pistol_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
